export default ",\\n            )\\n\\n    session.add(\\n        AuthzRoleAssignmentGrant(\\n            assignment_id=assignment.id,\\n            source_kind=\\\"manual\\\",\\n            administrative_actor=current_user.id,\\n        )\\n    )\\n    mutation = AuthorizationMutation(\\n        kind=AuthorizationMutationKind.ROLE_ASSIGNMENT_CREATED,\\n        entity_id=assignment.id,\\n        actor_user_id=current_user.id,\\n        affected_user_ids=(payload.user_id,),\\n        role_id=payload.role_id,\\n        domain_type=payload.domain_type,\\n        domain_id=payload.domain_id,\\n        policy_relevant_fields=(\\\"user_id\\\", \\\"role_id\\\", \\\"domain_type\\\", \\\"domain_id\\\"),\\n    )\\n    try:\\n        await session.flush()\\n        if effective_assignment_created:\\n            await stage_identity_mutation(authorization_service, session, mutation)\\n        await session.commit()\\n    except IntegrityError as exc:\\n        await session.rollback()\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"role_assignment:create\\\",\\n            obj=\\\"role_assignment:*\\\",\\n            status_code=status.HTTP_409_CONFLICT,\\n            reason=\\\"assignment_conflict\\\",\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=\\\"Assignment already exists for this user/role/domain\\\",\\n        ) from exc\\n    if effective_assignment_created:\\n        await safe_identity_mutation_committed(authorization_service, mutation)\\n    await session.refresh(assignment)\\n    await audit_decision(\\n        user_id=current_user.id,\\n        action=\\\"role_assignment:create\\\",\\n        obj=f\\\"role_assignment:{assignment.id}\\\",\\n        result=\\\"allow\\\",\\n        details={\\n            \\\"event\\\": AUDIT_EVENT_MUTATION,\\n            \\\"assignment_id\\\": str(assignment.id),\\n            \\\"subject_type\\\": \\\"user\\\",\\n            \\\"user_id\\\": str(payload.user_id),\\n            \\\"role_id\\\": str(payload.role_id),\\n            \\\"role_name\\\": role.name,\\n            \\\"domain_type\\\": payload.domain_type,\\n            \\\"domain_id\\\": str(payload.domain_id) if payload.domain_id else None,\\n        },\\n    )\\n    logger.info(\\n        \\\"Assigned role=%s to user=%s (domain=%s/%s)\\\",\\n        role.name,\\n        payload.user_id,\\n        payload.domain_type,\\n        payload.domain_id,\\n    )\\n    return (await _assignment_reads(session, [assignment]))[0]\\n\\n\\n@router.delete(\\n    \\\"/{assignment_id}\\\",\\n    response_model=RoleAssignmentRead,\\n    status_code=status.HTTP_200_OK,\\n    responses={status.HTTP_204_NO_CONTENT: {\\\"description\\\": \\\"Manual assignment fully revoked.\\\"}},\\n    dependencies=SUPERUSER_ONLY,\\n)\\nasync def delete_assignment(\\n    assignment_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> RoleAssignmentRead | Response:\\n    \\\"\\\"\\\"Remove a manual grant, returning the assignment when another source preserves it.\\\"\\\"\\\"\\n    await _require_superuser(\\n        current_user,\\n        action=\\\"role_assignment:delete\\\",\\n        obj=f\\\"role_assignment:{assignment_id}\\\",\\n    )\\n\\n    authorization_service = get_authorization_service()\\n    await acquire_identity_mutation_lock(\\n        authorization_service,\\n        session,\\n        kind=AuthorizationMutationKind.ROLE_ASSIGNMENT_DELETED,\\n        entity_id=assignment_id,\\n    )\\n\\n    # Re-read the assignment and all provenance under row locks on dialects\\n    # that support SELECT FOR UPDATE after the plugin's lock-only preflight.\\n    # Validation remains reserved for an actual effective-row deletion,\\n    # preserving existing hook semantics when only a manual source is removed.\\n    assignment = await session.get(\\n        AuthzRoleAssignment,\\n        assignment_id,\\n        populate_existing=True,\\n        with_for_update=True,\\n    )\\n    if assignment is None:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"role_assignment:delete\\\",\\n            obj=f\\\"role_assignment:{assignment_id}\\\",\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            reason=\\\"assignment_not_found\\\",\\n        )\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Assignment not found\\\")\\n    grants = (\\n        await session.exec(\\n            select(AuthzRoleAssignmentGrant)\\n            .where(AuthzRoleAssignmentGrant.assignment_id == assignment_id)\\n            .with_for_update()\\n            .execution_options(populate_existing=True)\\n        )\\n    ).all()\\n    manual_grant = next((grant for grant in grants if grant.source_kind == \\\"manual\\\"), None)\\n    if grants and manual_grant is None:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"role_assignment:delete\\\",\\n            obj=f\\\"role_assignment:{assignment_id}\\\",\\n            status_code=status.HTTP_409_CONFLICT,\\n            reason=\\\"idp_assignment_delete_forbidden\\\",\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=\\\"IdP-derived assignments cannot be deleted through the manual assignment API\\\",\\n        )\\n    if manual_grant is not None and len(grants) > 1:\\n        surviving_grants = [grant for grant in grants if grant is not manual_grant]\\n        await session.delete(manual_grant)\\n        await session.commit()\\n        await audit_decision(\\n            user_id=current_user.id,\\n            action=\\\"role_assignment:delete_manual_source\\\",\\n            obj=f\\\"role_assignment:{assignment_id}\\\",\\n            result=\\\"allow\\\",\\n            details={\\n                \\\"event\\\": AUDIT_EVENT_MUTATION,\\n                \\\"assignment_id\\\": str(assignment_id),\\n                \\\"subject_type\\\": \\\"user\\\",\\n                \\\"user_id\\\": str(assignment.user_id),\\n                \\\"role_id\\\": str(assignment.role_id),\\n                \\\"domain_type\\\": assignment.domain_type,\\n                \\\"domain_id\\\": str(assignment.domain_id) if assignment.domain_id else None,\\n                \\\"effective_assignment_preserved\\\": True,\\n                \\\"surviving_grant_sources\\\": [\\n                    {\\n                        \\\"source_kind\\\": grant.source_kind,\\n                        \\\"provider_id\\\": grant.provider_id,\\n                        \\\"external_group\\\": grant.external_group,\\n                    }\\n                    for grant in surviving_grants\\n                ],\\n            },\\n        )\\n        return RoleAssignmentRead.model_validate(assignment).model_copy(\\n            update={\\\"grant_sources\\\": [RoleAssignmentGrantSummary.model_validate(grant) for grant in surviving_grants]}\\n        )\\n\\n    user_id = assignment.user_id\\n    role_id = assignment.role_id\\n    domain_type = assignment.domain_type\\n    domain_id = assignment.domain_id\\n    mutation = AuthorizationMutation(\\n        kind=AuthorizationMutationKind.ROLE_ASSIGNMENT_DELETED,\\n        entity_id=assignment_id,\\n        actor_user_id=current_user.id,\\n        affected_user_ids=(user_id,),\\n        role_id=role_id,\\n        domain_type=domain_type,\\n        domain_id=domain_id,\\n        policy_relevant_fields=(\\\"user_id\\\", \\\"role_id\\\", \\\"domain_type\\\", \\\"domain_id\\\"),\\n    )\\n    try:\\n        await validate_identity_mutation(authorization_service, session, mutation)\\n    except AuthorizationMutationRejected as exc:\\n        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail=exc.public_detail) from exc\\n\\n    await session.delete(assignment)\\n    await session.flush()\\n    await stage_identity_mutation(authorization_service, session, mutation)\\n    await session.commit()\\n    await safe_identity_mutation_committed(authorization_service, mutation)\\n    await audit_decision(\\n        user_id=current_user.id,\\n        action=\\\"role_assignment:delete\\\",\\n        obj=f\\\"role_assignment:{assignment_id}\\\",\\n        result=\\\"allow\\\",\\n        details={\\n            \\\"event\\\": AUDIT_EVENT_MUTATION,\\n            \\\"assignment_id\\\": str(assignment_id),\\n            \\\"subject_type\\\": \\\"user\\\",\\n            \\\"user_id\\\": str(user_id),\\n            \\\"role_id\\\": str(role_id),\\n            \\\"domain_type\\\": domain_type,\\n            \\\"domain_id\\\": str(domain_id) if domain_id else None,\\n        },\\n    )\\n    logger.info(\\\"Revoked role assignment id=%s (user=%s)\\\", assignment_id, user_id)\\n    return Response(status_code=status.HTTP_204_NO_CONTENT)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/authz_roles.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"13d40f29f612aeaf619abf4fb95010c880c0113e30af6da1aae3b125a7fe17e4\",\"content\":\"\\\"\\\"\\\"CRUD API for authz_role rows (enforcement is delegated to authorization plugins).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timezone\\nfrom typing import Annotated\\nfrom uuid import UUID\\n\\nfrom fastapi import APIRouter, Depends, HTTPException, Query, Request, status\\nfrom lfx.log.logger import logger\\nfrom lfx.services.authorization import AuthorizationMutation, AuthorizationMutationKind\\nfrom lfx.utils.util_strings import escape_like_pattern\\nfrom sqlalchemy.exc import IntegrityError\\nfrom sqlmodel import select\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSession\\nfrom langflow.api.v1.schemas.authz_roles import RoleCreate, RoleRead, RoleUpdate\\nfrom langflow.services.authorization.audit import AUDIT_EVENT_ACCESS, AUDIT_EVENT_MUTATION\\nfrom langflow.services.authorization.lifecycle import (\\n    acquire_identity_mutation_lock,\\n    safe_identity_mutation_committed,\\n    stage_identity_mutation,\\n)\\nfrom langflow.services.authorization.utils import audit_decision\\nfrom langflow.services.database.models.auth import AuthzRole, AuthzRoleAssignment\\nfrom langflow.services.deps import get_authorization_service\\n\\nrouter = APIRouter(prefix=\\\"/authz/roles\\\", tags=[\\\"Authorization\\\"], include_in_schema=False)\\n\\n# Match ``authz_shares``: cap any single list call so an authenticated client\\n# (or a buggy frontend) can't enumerate the entire role/team catalog in one\\n# request. 100 default / 200 max is enough for typical UI dropdowns.\\n_LIST_MAX_LIMIT = 200\\n_LIST_DEFAULT_LIMIT = 100\\n_POSTGRES_UNIQUE_VIOLATION_SQLSTATE = \\\"23505\\\"\\n_ROLE_NAME_UNIQUE_INDEX = \\\"ix_authz_role_name\\\"\\n_SQLITE_ROLE_NAME_UNIQUE_MARKER = \\\"UNIQUE constraint failed: authz_role.name\\\"\\n\\n\\nasync def _audit_deny(*, user_id: UUID, action: str, obj: str, status_code: int, reason: str) -> None:\\n    await audit_decision(\\n        user_id=user_id,\\n        action=action,\\n        obj=obj,\\n        result=\\\"deny\\\",\\n        details={\\\"event\\\": AUDIT_EVENT_ACCESS, \\\"status_code\\\": status_code, \\\"reason\\\": reason},\\n    )\\n\\n\\ndef _is_role_name_conflict(exc: IntegrityError) -> bool:\\n    \\\"\\\"\\\"Return whether an integrity failure is specifically role-name uniqueness.\\\"\\\"\\\"\\n    current: BaseException | None = exc\\n    constraint_name: str | None = None\\n    is_unique_violation = False\\n    seen: set[int] = set()\\n    while current is not None and id(current) not in seen:\\n        seen.add(id(current))\\n        if _SQLITE_ROLE_NAME_UNIQUE_MARKER in str(current):\\n            return True\\n        sqlstate = getattr(current, \\\"sqlstate\\\", None) or getattr(current, \\\"pgcode\\\", None)\\n        is_unique_violation = is_unique_violation or sqlstate == _POSTGRES_UNIQUE_VIOLATION_SQLSTATE\\n        diagnostic = getattr(current, \\\"diag\\\", None)\\n        candidate = getattr(diagnostic, \\\"constraint_name\\\", None) or getattr(current, \\\"constraint_name\\\", None)\\n        if candidate:\\n            constraint_name = str(candidate)\\n        current = getattr(current, \\\"orig\\\", None) or current.__cause__\\n    return is_unique_violation and constraint_name == _ROLE_NAME_UNIQUE_INDEX\\n\\n\\nasync def _require_superuser(user, *, action: str, obj: str) -> None:\\n    \\\"\\\"\\\"Superuser-only gate. Role admin is an operations action.\\\"\\\"\\\"\\n    if not getattr(user, \\\"is_superuser\\\", False):\\n        await _audit_deny(\\n            user_id=user.id,\\n            action=action,\\n            obj=obj,\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            reason=\\\"superuser_required\\\",\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=\\\"Superuser required to administer roles.\\\",\\n        )\\n\\n\\nasync def _require_superuser_dependency(request: Request, current_user: CurrentActiveUser) -> None:\\n    \\\"\\\"\\\"Run the superuser gate as a route dependency, i.e. before body validation.\\n\\n    FastAPI solves a route's ``dependencies`` before validating that route's own\\n    body, so an unauthorised caller is refused whatever they post. Gated only in\\n    the endpoint body, they first receive the same 422 field names and enum\\n    values a superuser would, which lets them map the request contract of a\\n    route they cannot invoke.\\n\\n    The in-body call is kept as well: it is the gate for anything that reaches\\n    the endpoint function without FastAPI resolving dependencies.\\n    \\\"\\\"\\\"\\n    role_id = request.path_params.get(\\\"role_id\\\", \\\"*\\\")\\n    action = {\\\"POST\\\": \\\"role:create\\\", \\\"PATCH\\\": \\\"role:update\\\", \\\"DELETE\\\": \\\"role:delete\\\"}.get(\\n        request.method,\\n        \\\"role:access\\\",\\n    )\\n    await _require_superuser(current_user, action=action, obj=f\\\"role:{role_id}\\\")\\n\\n\\nSUPERUSER_ONLY = [Depends(_require_superuser_dependency)]\\n\\n\\nasync def _detect_parent_cycle(\\n    session: DbSession,\\n    *,\\n    role_id: UUID,\\n    proposed_parent_id: UUID,\\n) -> bool:\\n    \\\"\\\"\\\"Walk the parent chain from ``proposed_parent_id``; True if ``role_id`` appears.\\n\\n    Used to reject ``PATCH`` requests that would set a role as its own ancestor.\\n    Walks at most ``len(all_roles)`` steps so a pre-existing cycle terminates.\\n    \\\"\\\"\\\"\\n    visited: set[UUID] = set()\\n    cursor: UUID | None = proposed_parent_id\\n    while cursor is not None and cursor not in visited:\\n        if cursor == role_id:\\n            return True\\n        visited.add(cursor)\\n        parent = await session.get(AuthzRole, cursor)\\n        if parent is None:\\n            return False\\n        cursor = parent.parent_role_id\\n    return False\\n\\n\\n@router.get(\\\"\\\", response_model=list[RoleRead])\\n@router.get(\\\"/\\\", response_model=list[RoleRead])\\nasync def list_roles(\\n    session: DbSession,\\n    current_user: CurrentActiveUser,  # noqa: ARG001 \u2014 any authenticated user can list\\n    is_system: Annotated[bool | None, Query(description=\\\"Filter by is_system flag\\\")] = None,\\n    name: Annotated[str | None, Query(description=\\\"Substring match on role name\\\")] = None,\\n    limit: Annotated[int, Query(ge=1, le=_LIST_MAX_LIMIT)] = _LIST_DEFAULT_LIMIT,\\n    offset: Annotated[int, Query(ge=0)] = 0,\\n) -> list[RoleRead]:\\n    \\\"\\\"\\\"List roles. Open to authenticated users so the UI can populate dropdowns.\\n\\n    Paginated via ``limit`` / ``offset`` so a single call cannot return the\\n    entire catalog of roles + their permissions. Stable order is ``(name, id)``\\n    so ``offset`` is deterministic across calls.\\n    \\\"\\\"\\\"\\n    stmt = select(AuthzRole)\\n    if is_system is not None:\\n        stmt = stmt.where(AuthzRole.is_system == is_system)\\n    if name:\\n        stmt = stmt.where(AuthzRole.name.ilike(f\\\"%{escape_like_pattern(name)}%\\\", escape=\\\"\\\\\\\\\\\"))\\n    stmt = stmt.order_by(AuthzRole.name, AuthzRole.id).offset(offset).limit(limit)\\n    rows = (await session.exec(stmt)).all()\\n    return [RoleRead.model_validate(row) for row in rows]\\n\\n\\n@router.get(\\\"/{role_id}\\\", response_model=RoleRead)\\nasync def read_role(\\n    role_id: UUID,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,  # noqa: ARG001 \u2014 any authenticated user can read\\n) -> RoleRead:\\n    role = await session.get(AuthzRole, role_id)\\n    if role is None:\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Role not found\\\")\\n    return RoleRead.model_validate(role)\\n\\n\\n@router.post(\\\"\\\", response_model=RoleRead, status_code=status.HTTP_201_CREATED, dependencies=SUPERUSER_ONLY)\\n@router.post(\\\"/\\\", response_model=RoleRead, status_code=status.HTTP_201_CREATED, dependencies=SUPERUSER_ONLY)\\nasync def create_role(\\n    payload: RoleCreate,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> RoleRead:\\n    \\\"\\\"\\\"Create a custom (non-system) role. Superuser-only.\\\"\\\"\\\"\\n    await _require_superuser(current_user, action=\\\"role:create\\\", obj=\\\"role:*\\\")\\n    authorization_service = get_authorization_service()\\n    await acquire_identity_mutation_lock(\\n        authorization_service,\\n        session,\\n        kind=AuthorizationMutationKind.ROLE_CREATED,\\n    )\\n\\n    if payload.parent_role_id is not None:\\n        parent = await session.get(AuthzRole, payload.parent_role_id)\\n        if parent is None:\\n            await _audit_deny(\\n                user_id=current_user.id,\\n                action=\\\"role:create\\\",\\n                obj=\\\"role:*\\\",\\n                status_code=status.HTTP_400_BAD_REQUEST,\\n                reason=\\\"parent_role_not_found\\\",\\n            )\\n            raise HTTPException(\\n                status_code=status.HTTP_400_BAD_REQUEST,\\n                detail=\\\"parent_role_id does not reference an existing role\\\",\\n            )\\n\\n    role = AuthzRole(\\n        name=payload.name,\\n        description=payload.description,\\n        is_system=False,\\n        permissions=list(payload.permissions),\\n        parent_role_id=payload.parent_role_id,\\n        created_by=current_user.id,\\n    )\\n    session.add(role)\\n    mutation = AuthorizationMutation(\\n        kind=AuthorizationMutationKind.ROLE_CREATED,\\n        entity_id=role.id,\\n        actor_user_id=current_user.id,\\n        role_id=role.id,\\n        policy_relevant_fields=(\\\"name\\\", \\\"permissions\\\", \\\"parent_role_id\\\"),\\n    )\\n    try:\\n        await session.flush()\\n        await stage_identity_mutation(authorization_service, session, mutation)\\n        await session.commit()\\n    except IntegrityError as exc:\\n        await session.rollback()\\n        is_name_conflict = _is_role_name_conflict(exc)\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"role:create\\\",\\n            obj=\\\"role:*\\\",\\n            status_code=status.HTTP_409_CONFLICT,\\n            reason=\\\"role_name_conflict\\\" if is_name_conflict else \\\"role_integrity_conflict\\\",\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=(\\n                f\\\"Role with name {payload.name!r} already exists\\\"\\n                if is_name_conflict\\n                else \\\"Role data conflicts with the current database state\\\"\\n            ),\\n        ) from exc\\n    await safe_identity_mutation_committed(authorization_service, mutation)\\n    await session.refresh(role)\\n    await audit_decision(\\n        user_id=current_user.id,\\n        action=\\\"role:create\\\",\\n        obj=f\\\"role:{role.id}\\\",\\n        result=\\\"allow\\\",\\n        details={\\n            \\\"event\\\": AUDIT_EVENT_MUTATION,\\n            \\\"role_name\\\": role.name,\\n            \\\"permissions\\\": list(role.permissions),\\n            \\\"parent_role_id\\\": str(role.parent_role_id) if role.parent_role_id else None,\\n        },\\n    )\\n    logger.info(\\\"Created role %s (id=%s)\\\", role.name, role.id)\\n    return RoleRead.model_validate(role)\\n\\n\\n@router.patch(\\\"/{role_id}\\\", response_model=RoleRead, dependencies=SUPERUSER_ONLY)\\nasync def update_role(\\n    role_id: UUID,\\n    payload: RoleUpdate,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> RoleRead:\\n    \\\"\\\"\\\"Update fields on a custom role. System roles are read-only.\\\"\\\"\\\"\\n    await _require_superuser(current_user, action=\\\"role:update\\\", obj=f\\\"role:{role_id}\\\")\\n    authorization_service = get_authorization_service()\\n    await acquire_identity_mutation_lock(\\n        authorization_service,\\n        session,\\n        kind=AuthorizationMutationKind.ROLE_UPDATED,\\n        entity_id=role_id,\\n    )\\n\\n    role = await session.get(AuthzRole, role_id)\\n    if role is None:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"role:update\\\",\\n            obj=f\\\"role:{role_id}\\\",\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            reason=\\\"role_not_found\\\",\\n        )\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Role not found\\\")\\n    if role.is_system:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"role:update\\\",\\n            obj=f\\\"role:{role_id}\\\",\\n            status_code=status.HTTP_400_BAD_REQUEST,\\n            reason=\\\"system_role_read_only\\\",\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_400_BAD_REQUEST,\\n            detail=\\\"System roles cannot be modified\\\",\\n        )\\n\\n    # Use presence checks (model_fields_set) rather than ``is not None`` so PATCH\\n    # can clear nullable fields. An explicit ``\\\"description\\\": null`` in the body\\n    # marks the field as set and assigns None; omitting it leaves the row alone.\\n    fields_set = payload.model_fields_set\\n    previous_name = role.name\\n\\n    if \\\"parent_role_id\\\" in fields_set:\\n        if payload.parent_role_id is None:\\n            role.parent_role_id = None\\n        else:\\n            if payload.parent_role_id == role.id:\\n                await _audit_deny(\\n                    user_id=current_user.id,\\n                    action=\\\"role:update\\\",\\n                    obj=f\\\"role:{role_id}\\\",\\n                    status_code=status.HTTP_400_BAD_REQUEST,\\n                    reason=\\\"self_parent_forbidden\\\",\\n                )\\n                raise HTTPException(\\n                    status_code=status.HTTP_400_BAD_REQUEST,\\n                    detail=\\\"A role cannot be its own parent\\\",\\n                )\\n            parent = await session.get(AuthzRole, payload.parent_role_id)\\n            if parent is None:\\n                await _audit_deny(\\n                    user_id=current_user.id,\\n                    action=\\\"role:update\\\",\\n                    obj=f\\\"role:{role_id}\\\",\\n                    status_code=status.HTTP_400_BAD_REQUEST,\\n                    reason=\\\"parent_role_not_found\\\",\\n                )\\n                raise HTTPException(\\n                    status_code=status.HTTP_400_BAD_REQUEST,\\n                    detail=\\\"parent_role_id does not reference an existing role\\\",\\n                )\\n            if await _detect_parent_cycle(session, role_id=role.id, proposed_parent_id=payload.parent_role_id):\\n                await _audit_deny(\\n                    user_id=current_user.id,\\n                    action=\\\"role:update\\\",\\n                    obj=f\\\"role:{role_id}\\\",\\n                    status_code=status.HTTP_400_BAD_REQUEST,\\n                    reason=\\\"role_hierarchy_cycle\\\",\\n                )\\n                raise HTTPException(\\n                    status_code=status.HTTP_400_BAD_REQUEST,\\n                    detail=\\\"Setting this parent would create a role hierarchy cycle\\\",\\n                )\\n            role.parent_role_id = payload.parent_role_id\\n\\n    if \\\"description\\\" in fields_set:\\n        # description is nullable on the DB side \u2014 None is a legitimate clear.\\n        role.description = payload.description\\n\\n    if \\\"name\\\" in fields_set:\\n        # name is NOT NULL + unique on the DB side; reject an explicit null at\\n        # the boundary so the caller gets a clear 400 instead of an opaque\\n        # IntegrityError that the catch block below mislabels as \\\"Name conflict\\\".\\n        if payload.name is None:\\n            await _audit_deny(\\n                user_id=current_user.id,\\n                action=\\\"role:update\\\",\\n                obj=f\\\"role:{role_id}\\\",\\n                status_code=status.HTTP_400_BAD_REQUEST,\\n                reason=\\\"null_name_forbidden\\\",\\n            )\\n            raise HTTPException(\\n                status_code=status.HTTP_400_BAD_REQUEST,\\n                detail=\\\"name cannot be null\\\",\\n            )\\n        role.name = payload.name\\n\\n    if \\\"permissions\\\" in fields_set:\\n        # permissions column is nullable=False (default_factory=list). An empty\\n        # list is the natural \\\"clear\\\" \u2014 None would violate the constraint at\\n        # commit, so reject it up front.\\n        if payload.permissions is None:\\n            await _audit_deny(\\n                user_id=current_user.id,\\n                action=\\\"role:update\\\",\\n                obj=f\\\"role:{role_id}\\\",\\n                status_code=status.HTTP_400_BAD_REQUEST,\\n                reason=\\\"null_permissions_forbidden\\\",\\n            )\\n            raise HTTPException(\\n                status_code=status.HTTP_400_BAD_REQUEST,\\n                detail=\\\"permissions cannot be null; pass an empty list to clear\\\",\\n            )\\n        role.permissions = list(payload.permissions)\\n\\n    role.updated_at = datetime.now(timezone.utc)\\n    mutation = AuthorizationMutation(\\n        kind=AuthorizationMutationKind.ROLE_UPDATED,\\n        entity_id=role.id,\\n        actor_user_id=current_user.id,\\n        role_id=role.id,\\n        policy_relevant_fields=tuple(sorted(fields_set & {\\\"name\\\", \\\"permissions\\\", \\\"parent_role_id\\\"})),\\n        previous_identifier=previous_name if role.name != previous_name else None,\\n    )\\n    try:\\n        await session.flush()\\n        await stage_identity_mutation(authorization_service, session, mutation)\\n        await session.commit()\\n    except IntegrityError as exc:\\n        await session.rollback()\\n        is_name_conflict = _is_role_name_conflict(exc)\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"role:update\\\",\\n            obj=f\\\"role:{role_id}\\\",\\n            status_code=status.HTTP_409_CONFLICT,\\n            reason=\\\"role_name_conflict\\\" if is_name_conflict else \\\"role_integrity_conflict\\\",\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=(\\n                \\\"Name conflict \u2014 another role already uses this name\\\"\\n                if is_name_conflict\\n                else \\\"Role data conflicts with the current database state\\\"\\n            ),\\n        ) from exc\\n    await safe_identity_mutation_committed(authorization_service, mutation)\\n    await session.refresh(role)\\n    await audit_decision(\\n        user_id=current_user.id,\\n        action=\\\"role:update\\\",\\n        obj=f\\\"role:{role.id}\\\",\\n        result=\\\"allow\\\",\\n        details={\\n            \\\"event\\\": AUDIT_EVENT_MUTATION,\\n            \\\"role_name\\\": role.name,\\n            \\\"fields_changed\\\": sorted(fields_set),\\n        },\\n    )\\n    logger.info(\\\"Updated role %s (id=%s)\\\", role.name, role.id)\\n    return RoleRead.model_validate(role)\\n\\n\\n@router.delete(\\\"/{role_id}\\\", status_code=status.HTTP_204_NO_CONTENT, dependencies=SUPERUSER_ONLY)\\nasync def delete_role(\\n    role_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> None:\\n    \\\"\\\"\\\"Delete a custom role.\\n\\n    System roles cannot be deleted; roles with active assignments return 409\\n    (delete the assignments first).\\n    \\\"\\\"\\\"\\n    await _require_superuser(current_user, action=\\\"role:delete\\\", obj=f\\\"role:{role_id}\\\")\\n    authorization_service = get_authorization_service()\\n    await acquire_identity_mutation_lock(\\n        authorization_service,\\n        session,\\n        kind=AuthorizationMutationKind.ROLE_DELETED,\\n        entity_id=role_id,\\n    )\\n\\n    role = await session.get(AuthzRole, role_id)\\n    if role is None:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"role:delete\\\",\\n            obj=f\\\"role:{role_id}\\\",\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            reason=\\\"role_not_found\\\",\\n        )\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Role not found\\\")\\n    if role.is_system:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"role:delete\\\",\\n            obj=f\\\"role:{role_id}\\\",\\n            status_code=status.HTTP_400_BAD_REQUEST,\\n            reason=\\\"system_role_read_only\\\",\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_400_BAD_REQUEST,\\n            detail=\\\"System roles cannot be deleted\\\",\\n        )\\n\\n    assigned = (\\n        await session.exec(select(AuthzRoleAssignment).where(AuthzRoleAssignment.role_id == role_id).limit(1))\\n    ).first()\\n    if assigned is not None:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"role:delete\\\",\\n            obj=f\\\"role:{role_id}\\\",\\n            status_code=status.HTTP_409_CONFLICT,\\n            reason=\\\"active_assignments_exist\\\",\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=\\\"Role still has active assignments \u2014 revoke them before deleting\\\",\\n        )\\n\\n    role_name = role.name\\n    mutation = AuthorizationMutation(\\n        kind=AuthorizationMutationKind.ROLE_DELETED,\\n        entity_id=role_id,\\n        actor_user_id=current_user.id,\\n        role_id=role_id,\\n        policy_relevant_fields=(\\\"name\\\", \\\"permissions\\\", \\\"parent_role_id\\\"),\\n        previous_identifier=role_name,\\n    )\\n    await session.delete(role)\\n    await session.flush()\\n    await stage_identity_mutation(authorization_service, session, mutation)\\n    await session.commit()\\n    await safe_identity_mutation_committed(authorization_service, mutation)\\n    await audit_decision(\\n        user_id=current_user.id,\\n        action=\\\"role:delete\\\",\\n        obj=f\\\"role:{role_id}\\\",\\n        result=\\\"allow\\\",\\n        details={\\\"event\\\": AUDIT_EVENT_MUTATION, \\\"role_name\\\": role_name},\\n    )\\n    logger.info(\\\"Deleted role id=%s\\\", role_id)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/authz_route_dependencies.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9f1f4ef21ace090481b27bbb7ae60f1b211987b3e5066ac609c8f8865ce9a540\",\"content\":\"\\\"\\\"\\\"FastAPI dependencies that fetch a resource and enforce authorization in one step.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Annotated\\nfrom uuid import UUID\\n\\nfrom fastapi import Depends, HTTPException, status\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSession\\nfrom langflow.api.v1.flows_helpers import _canonicalize_flow_destination, _read_flow\\nfrom langflow.services.authorization import FlowAction, ensure_flow_permission\\nfrom langflow.services.authorization.fetch import deny_to_404\\nfrom langflow.services.database.models.flow.model import Flow, FlowCreate\\nfrom langflow.services.database.models.folder.model import Folder\\n\\n_FLOW_WRITE_DENIED_DETAIL = \\\"You don't have permission to edit this flow.\\\"\\n_FLOW_DELETE_DENIED_DETAIL = \\\"You don't have permission to delete this flow.\\\"\\n\\n\\nasync def _get_authorized_flow(\\n    act: FlowAction,\\n    *,\\n    flow_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> Flow:\\n    \\\"\\\"\\\"Load a flow (share-aware when the plugin supports it) and enforce *act*.\\\"\\\"\\\"\\n    flow = await _read_flow(session, flow_id, current_user.id)\\n    if flow is None:\\n        raise HTTPException(status_code=404, detail=\\\"Flow not found\\\")\\n    try:\\n        await ensure_flow_permission(\\n            current_user,\\n            act,\\n            flow_id=flow_id,\\n            flow_user_id=flow.user_id,\\n            workspace_id=flow.workspace_id,\\n            folder_id=flow.folder_id,\\n        )\\n    except HTTPException as exc:\\n        if act in (FlowAction.WRITE, FlowAction.DELETE) and exc.status_code == status.HTTP_403_FORBIDDEN:\\n            try:\\n                await ensure_flow_permission(\\n                    current_user,\\n                    FlowAction.READ,\\n                    flow_id=flow_id,\\n                    flow_user_id=flow.user_id,\\n                    workspace_id=flow.workspace_id,\\n                    folder_id=flow.folder_id,\\n                )\\n            except HTTPException as read_exc:\\n                raise deny_to_404(read_exc, detail=\\\"Flow not found\\\") from read_exc\\n            denied_detail = _FLOW_WRITE_DENIED_DETAIL if act == FlowAction.WRITE else _FLOW_DELETE_DENIED_DETAIL\\n            raise HTTPException(status_code=403, detail=denied_detail) from exc\\n        raise deny_to_404(exc, detail=\\\"Flow not found\\\") from exc\\n    return flow\\n\\n\\nasync def get_authorized_flow_for_read(\\n    flow_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> Flow:\\n    \\\"\\\"\\\"Return a flow the caller may read (404 when denied or missing).\\\"\\\"\\\"\\n    return await _get_authorized_flow(FlowAction.READ, flow_id=flow_id, current_user=current_user, session=session)\\n\\n\\nasync def get_authorized_flow_for_write(\\n    flow_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> Flow:\\n    \\\"\\\"\\\"Return a flow the caller may write (403 when readable but not writable, 404 otherwise).\\\"\\\"\\\"\\n    return await _get_authorized_flow(FlowAction.WRITE, flow_id=flow_id, current_user=current_user, session=session)\\n\\n\\nasync def get_authorized_flow_for_delete(\\n    flow_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> Flow:\\n    \\\"\\\"\\\"Return a flow the caller may delete (403 when readable but not deletable, 404 otherwise).\\\"\\\"\\\"\\n    return await _get_authorized_flow(FlowAction.DELETE, flow_id=flow_id, current_user=current_user, session=session)\\n\\n\\nasync def require_flow_create_permission(\\n    current_user: CurrentActiveUser,\\n    flow: FlowCreate,\\n    session: DbSession,\\n) -> tuple[UUID | None, UUID]:\\n    \\\"\\\"\\\"Authorize CREATE at the destination workspace/folder before inserting a flow.\\\"\\\"\\\"\\n    destination = await _canonicalize_flow_destination(\\n        session,\\n        flow,\\n        current_user.id,\\n        widen_for_authz=True,\\n    )\\n    _, destination_folder_id = destination\\n    # Read the owner off the *resolved* destination rather than the payload:\\n    # canonicalization may have redirected an unusable folder_id to the\\n    # caller's default project, and only the stored row can say who owns the\\n    # project the flow will actually land in. This is what lets the owner\\n    # override cover creating a flow in a project you own \u2014 the new flow has no\\n    # owner of its own yet.\\n    destination_folder = await session.get(Folder, destination_folder_id)\\n    await ensure_flow_permission(\\n        current_user,\\n        FlowAction.CREATE,\\n        workspace_id=flow.workspace_id,\\n        folder_id=flow.folder_id,\\n        folder_user_id=getattr(destination_folder, \\\"user_id\\\", None),\\n    )\\n    return destination\\n\\n\\nAuthorizedReadFlow = Annotated[Flow, Depends(get_authorized_flow_for_read)]\\nAuthorizedWriteFlow = Annotated[Flow, Depends(get_authorized_flow_for_write)]\\nAuthorizedDeleteFlow = Annotated[Flow, Depends(get_authorized_flow_for_delete)]\\nRequireFlowCreate = Annotated[tuple[UUID | None, UUID], Depends(require_flow_create_permission)]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/authz_shares.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"47fbfd8ce7ed778e6c65687d85570348380f095bc86e6f95a829a142803a7eb7\",\"content\":\"\\\"\\\"\\\"CRUD API for authz_share rows (enforcement is delegated to authorization plugins).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nfrom collections.abc import Awaitable\\nfrom datetime import datetime, timezone\\nfrom typing import Annotated\\nfrom uuid import UUID\\n\\nfrom fastapi import APIRouter, HTTPException, Query, status\\nfrom lfx.log.logger import logger\\nfrom lfx.services.authorization.base import BaseAuthorizationService, ShareRuleSnapshot\\nfrom sqlmodel import select\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSession\\nfrom langflow.api.v1.schemas.authz_shares import ShareCreate, ShareRead, ShareUpdate\\nfrom langflow.services.authorization import ShareAction, ensure_share_permission\\nfrom langflow.services.authorization.audit import AUDIT_EVENT_MUTATION\\nfrom langflow.services.authorization.fetch import deny_to_404\\nfrom langflow.services.authorization.utils import audit_decision\\nfrom langflow.services.database.models.auth import (\\n    AuthzShare,\\n    AuthzTeam,\\n    AuthzTeamMember,\\n    SharePermissionLevel,\\n    ShareScope,\\n)\\nfrom langflow.services.database.models.deployment.model import Deployment\\nfrom langflow.services.database.models.file.model import File as UserFile\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.database.models.knowledge_base.model import KnowledgeBaseRecord\\nfrom langflow.services.database.models.memory_base.model import MemoryBase\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.database.models.variable.model import Variable\\nfrom langflow.services.deps import get_authorization_service\\n\\nrouter = APIRouter(prefix=\\\"/authz/shares\\\", tags=[\\\"Authorization\\\"], include_in_schema=False)\\n\\n_SHARE_POLICY_HOOK_TIMEOUT_SECONDS = 5.0\\n\\n\\n# resource_type slug \u2192 (model, owner column).\\n_RESOURCE_OWNER_LOOKUPS: dict[str, tuple[type, str]] = {\\n    \\\"flow\\\": (Flow, \\\"user_id\\\"),\\n    \\\"deployment\\\": (Deployment, \\\"user_id\\\"),\\n    \\\"project\\\": (Folder, \\\"user_id\\\"),\\n    \\\"knowledge_base\\\": (KnowledgeBaseRecord, \\\"user_id\\\"),\\n    \\\"variable\\\": (Variable, \\\"user_id\\\"),\\n    \\\"file\\\": (UserFile, \\\"user_id\\\"),\\n}\\n\\n\\nasync def _resolve_resource_owner(\\n    session: DbSession,\\n    *,\\n    resource_type: str,\\n    resource_id: UUID,\\n) -> UUID | None:\\n    \\\"\\\"\\\"Return the owner ``user_id`` for the named resource, or None if not found.\\\"\\\"\\\"\\n    lookup = _RESOURCE_OWNER_LOOKUPS.get(resource_type)\\n    if lookup is None:\\n        return None\\n    model, owner_attr = lookup\\n    row = await session.get(model, resource_id)\\n    # Memory Bases share the ``knowledge_base`` authorization namespace, but\\n    # their ids live in ``memory_base`` rather than ``knowledge_base``. Keep a\\n    # single external resource type while resolving either backing model.\\n    if row is None and resource_type == \\\"knowledge_base\\\":\\n        row = await session.get(MemoryBase, resource_id)\\n    if row is None:\\n        return None\\n    return getattr(row, owner_attr, None)\\n\\n\\nasync def _serialize_shares(session: DbSession, rows: list[AuthzShare]) -> list[ShareRead]:\\n    \\\"\\\"\\\"Serialize shares with human-readable user and team target names.\\n\\n    ``target_id`` is polymorphic, so the database cannot expose a normal ORM\\n    relationship. Resolve each target kind in one query and keep the name\\n    optional for deleted or otherwise stale targets.\\n    \\\"\\\"\\\"\\n    user_ids = {row.target_id for row in rows if row.scope == ShareScope.USER.value and row.target_id is not None}\\n    team_ids = {row.target_id for row in rows if row.scope == ShareScope.TEAM.value and row.target_id is not None}\\n\\n    user_names: dict[UUID, str] = {}\\n    if user_ids:\\n        user_rows = await session.exec(select(User.id, User.username).where(User.id.in_(user_ids)))\\n        user_names.update(dict(user_rows.all()))\\n    team_names: dict[UUID, str] = {}\\n    if team_ids:\\n        team_rows = await session.exec(select(AuthzTeam.id, AuthzTeam.team_name).where(AuthzTeam.id.in_(team_ids)))\\n        team_names.update(dict(team_rows.all()))\\n\\n    def target_name(row: AuthzShare) -> str | None:\\n        if row.scope == ShareScope.USER.value:\\n            return user_names.get(row.target_id)\\n        if row.scope == ShareScope.TEAM.value:\\n            return team_names.get(row.target_id)\\n        return None\\n\\n    return [\\n        ShareRead.model_validate(row, from_attributes=True).model_copy(update={\\\"target_name\\\": target_name(row)})\\n        for row in rows\\n    ]\\n\\n\\ndef _share_visible(\\n    *,\\n    row: AuthzShare,\\n    user_id: UUID,\\n    resource_owner_id: UUID | None,\\n    is_team_member: bool,\\n) -> bool:\\n    \\\"\\\"\\\"Pure visibility predicate shared by the single-row and list paths.\\n\\n    ``is_team_member`` is resolved by the caller \u2014 a membership query for the\\n    single-row path, a pre-fetched team-id set for the list path \u2014 so this\\n    predicate stays free of I/O and the owner/PUBLIC/USER/TEAM rules live in one\\n    place.\\n    \\\"\\\"\\\"\\n    if user_id in {resource_owner_id, row.created_by}:\\n        return True\\n    scope = row.scope\\n    if scope == ShareScope.PUBLIC.value:\\n        # PUBLIC is a direct-link grant, not a discovery/listing grant.\\n        return False\\n    if scope == ShareScope.USER.value and row.target_id == user_id:\\n        return True\\n    if scope == ShareScope.TEAM.value and row.target_id is not None:\\n        return is_team_member\\n    return False\\n\\n\\ndef _active_team_ids_for_user(user_id: UUID):\\n    \\\"\\\"\\\"Select only active teams whose membership can confer share visibility.\\\"\\\"\\\"\\n    return (\\n        select(AuthzTeamMember.team_id)\\n        .join(AuthzTeam, AuthzTeam.id == AuthzTeamMember.team_id)\\n        .where(\\n            AuthzTeamMember.user_id == user_id,\\n            AuthzTeam.is_active.is_(True),\\n        )\\n    )\\n\\n\\nasync def _user_can_see_share(\\n    session: DbSession,\\n    *,\\n    row: AuthzShare,\\n    user_id: UUID,\\n    resource_owner_id: UUID | None,\\n) -> bool:\\n    \\\"\\\"\\\"Return True when the user may see this share row (single-row path).\\\"\\\"\\\"\\n    is_team_member = False\\n    if row.scope == ShareScope.TEAM.value and row.target_id is not None:\\n        membership_stmt = _active_team_ids_for_user(user_id).where(AuthzTeamMember.team_id == row.target_id)\\n        is_team_member = (await session.exec(membership_stmt)).first() is not None\\n    return _share_visible(\\n        row=row,\\n        user_id=user_id,\\n        resource_owner_id=resource_owner_id,\\n        is_team_member=is_team_member,\\n    )\\n\\n\\nasync def _try_bounded_invalidation(operation: Awaitable[None], *, hook_name: str, op: str) -> bool:\\n    \\\"\\\"\\\"Run one invalidation hook within the post-commit plugin deadline.\\\"\\\"\\\"\\n    try:\\n        await asyncio.wait_for(operation, timeout=_SHARE_POLICY_HOOK_TIMEOUT_SECONDS)\\n    except Exception as exc:  # noqa: BLE001 - post-commit plugin hooks are best-effort\\n        logger.warning(\\\"%s failed after %s; cache may be stale: %s\\\", hook_name, op, exc)\\n        return False\\n    return True\\n\\n\\nasync def _invalidate_for_share(scope: str, target_id: UUID | None, *, op: str = \\\"share:write\\\") -> None:\\n    \\\"\\\"\\\"Invalidate cached policy after a share write (user scope vs invalidate_all).\\\"\\\"\\\"\\n    authz = get_authorization_service()\\n    if scope == ShareScope.USER.value and target_id is not None:\\n        if await _try_bounded_invalidation(\\n            authz.invalidate_user(target_id),\\n            hook_name=\\\"invalidate_user\\\",\\n            op=op,\\n        ):\\n            return\\n        await _try_bounded_invalidation(\\n            authz.invalidate_all(),\\n            hook_name=\\\"invalidate_all fallback\\\",\\n            op=op,\\n        )\\n        return\\n    await _try_bounded_invalidation(\\n        authz.invalidate_all(),\\n        hook_name=\\\"invalidate_all\\\",\\n        op=op,\\n    )\\n\\n\\ndef _uses_base_sync_shares(authz: BaseAuthorizationService) -> bool:\\n    \\\"\\\"\\\"Return True when the service only has the OSS no-op sync_shares hook.\\\"\\\"\\\"\\n    return getattr(type(authz), \\\"sync_shares\\\", None) is BaseAuthorizationService.sync_shares\\n\\n\\ndef _overrides_share_hook(authz: BaseAuthorizationService, hook_name: str) -> bool:\\n    \\\"\\\"\\\"Return whether a plugin provides a non-base implementation of ``hook_name``.\\\"\\\"\\\"\\n    plugin_hook = getattr(type(authz), hook_name, None)\\n    base_hook = getattr(BaseAuthorizationService, hook_name)\\n    return plugin_hook is not None and plugin_hook is not base_hook\\n\\n\\nasync def _try_coarse_share_sync(authz: BaseAuthorizationService, *, op: str) -> bool:\\n    \\\"\\\"\\\"Run the legacy full-table hook when overridden, returning whether it succeeded.\\\"\\\"\\\"\\n    sync_shares = getattr(authz, \\\"sync_shares\\\", None)\\n    if sync_shares is not None and not _uses_base_sync_shares(authz):\\n        try:\\n            await asyncio.wait_for(\\n                sync_shares(),\\n                timeout=_SHARE_POLICY_HOOK_TIMEOUT_SECONDS,\\n            )\\n        except Exception as exc:  # noqa: BLE001 - plugin hooks are best-effort post-commit work\\n            logger.warning(\\\"sync_shares failed after %s; falling back to safe invalidation: %s\\\", op, exc)\\n        else:\\n            return True\\n    return False\\n\\n\\nasync def _refresh_policy_for_share(share_id: UUID, scope: str, target_id: UUID | None, *, op: str) -> None:\\n    \\\"\\\"\\\"Refresh one share after commit, then degrade through legacy-safe fallbacks.\\\"\\\"\\\"\\n    authz = get_authorization_service()\\n    if _overrides_share_hook(authz, \\\"sync_share\\\"):\\n        try:\\n            await asyncio.wait_for(\\n                authz.sync_share(share_id),\\n                timeout=_SHARE_POLICY_HOOK_TIMEOUT_SECONDS,\\n            )\\n        except Exception as exc:  # noqa: BLE001 - durable share writes must never be rolled back by plugin hooks\\n            logger.warning(\\\"sync_share failed after %s; falling back to sync_shares: %s\\\", op, exc)\\n        else:\\n            return\\n    if await _try_coarse_share_sync(authz, op=op):\\n        return\\n    await _invalidate_for_share(scope, target_id, op=op)\\n\\n\\nasync def _remove_policy_for_share(snapshot: ShareRuleSnapshot, *, op: str) -> None:\\n    \\\"\\\"\\\"Remove one deleted share's rules after commit, with coarse compatibility fallbacks.\\\"\\\"\\\"\\n    authz = get_authorization_service()\\n    if _overrides_share_hook(authz, \\\"remove_share_rules\\\"):\\n        try:\\n            await asyncio.wait_for(\\n                authz.remove_share_rules(snapshot),\\n                timeout=_SHARE_POLICY_HOOK_TIMEOUT_SECONDS,\\n            )\\n        except Exception as exc:  # noqa: BLE001 - durable share deletes must never be rolled back by plugin hooks\\n            logger.warning(\\\"remove_share_rules failed after %s; falling back to sync_shares: %s\\\", op, exc)\\n        else:\\n            return\\n    if await _try_coarse_share_sync(authz, op=op):\\n        return\\n    await _invalidate_for_share(snapshot.scope, snapshot.target_id, op=op)\\n\\n\\nasync def _ensure_can_administer_share(\\n    *,\\n    user: User,\\n    owner_id: UUID | None,\\n) -> None:\\n    \\\"\\\"\\\"Require resource owner or superuser unless cross-user enforcement is active.\\\"\\\"\\\"\\n    if getattr(user, \\\"is_superuser\\\", False):\\n        return\\n    if owner_id is not None and owner_id == user.id:\\n        return\\n    authz = get_authorization_service()\\n    if await authz.supports_cross_user_fetch() and await authz.is_enabled():\\n        # Why: in OSS, ``supports_cross_user_fetch()`` is False (see\\n        # LangflowAuthorizationService), so this early-return is dead and the\\n        # explicit 403 below is the floor. When an authorization plugin signals\\n        # cross-user fetch support, the plugin is the authoritative gate via\\n        # the ``ensure_share_permission()`` call that every share route makes\\n        # immediately after this helper. Removing that downstream call \u2014 or\\n        # weakening the plugin's cross-user fetch contract \u2014 REOPENS the\\n        # ownership gap. Keep the two in lockstep.\\n        return\\n    raise HTTPException(\\n        status_code=status.HTTP_403_FORBIDDEN,\\n        detail=\\\"Only the resource owner or a superuser may administer shares for this resource.\\\",\\n    )\\n\\n\\ndef _ensure_supported_share_permission(*, resource_type: str, scope: str, permission_level: str) -> None:\\n    \\\"\\\"\\\"Reject share levels that have no matching public flow product behavior.\\\"\\\"\\\"\\n    if resource_type != \\\"flow\\\" or scope != ShareScope.PUBLIC.value:\\n        return\\n    if permission_level == SharePermissionLevel.EXECUTE.value:\\n        return\\n    raise HTTPException(\\n        status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,\\n        detail=\\\"PUBLIC flow shares require permission_level 'execute'.\\\",\\n    )\\n\\n\\n@router.post(\\\"\\\", response_model=ShareRead, status_code=status.HTTP_201_CREATED)\\n@router.post(\\\"/\\\", response_model=ShareRead, status_code=status.HTTP_201_CREATED)\\nasync def create_share(\\n    payload: ShareCreate,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> ShareRead:\\n    \\\"\\\"\\\"Create an authz_share row for a resource.\\\"\\\"\\\"\\n    owner_id = await _resolve_resource_owner(\\n        session,\\n        resource_type=payload.resource_type,\\n        resource_id=payload.resource_id,\\n    )\\n    if owner_id is None:\\n        # UUID privacy: missing resource \u2192 404.\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Resource not found\\\")\\n    try:\\n        await _ensure_can_administer_share(user=current_user, owner_id=owner_id)\\n        # SECURITY: pass the *resource* owner (not the caller) so the owner-override\\n        # in ensure_share_permission only fast-paths the real resource owner. With\\n        # share_user_id=current_user.id the override would always trip and the\\n        # authorization plugin's enforce() would never run for non-owner creators\\n        # when the OSS floor is bypassed (cross_user_fetch + AUTHZ_ENABLED).\\n        await ensure_share_permission(\\n            current_user,\\n            ShareAction.CREATE,\\n            share_user_id=owner_id,\\n        )\\n        _ensure_supported_share_permission(\\n            resource_type=payload.resource_type,\\n            scope=payload.scope,\\n            permission_level=payload.permission_level,\\n        )\\n    except HTTPException as exc:\\n        raise deny_to_404(exc, detail=\\\"Resource not found\\\") from exc\\n\\n    row = AuthzShare(\\n        resource_type=payload.resource_type,\\n        resource_id=payload.resource_id,\\n        scope=payload.scope,\\n        target_id=payload.target_id,\\n        permission_level=payload.permission_level,\\n        created_by=current_user.id,\\n        created_at=datetime.now(timezone.utc),\\n    )\\n    session.add(row)\\n    try:\\n        await session.flush()\\n    except Exception as exc:\\n        # Log server-side; return a fixed 409 message (no schema leakage).\\n        await session.rollback()\\n        logger.warning(\\\"authz_share insert rejected: %s\\\", exc)\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=\\\"Share could not be created: it may already exist or conflict with an existing share.\\\",\\n        ) from exc\\n    await session.refresh(row)\\n    response = (await _serialize_shares(session, [row]))[0]\\n    await session.commit()\\n\\n    # Refresh policy after commit so plugins using a separate DB connection see\\n    # the durable authz_share row instead of the pre-commit transaction state.\\n    await _refresh_policy_for_share(response.id, payload.scope, payload.target_id, op=\\\"share:create\\\")\\n\\n    await audit_decision(\\n        user_id=current_user.id,\\n        action=\\\"share:create\\\",\\n        obj=f\\\"{payload.resource_type}:{payload.resource_id}\\\",\\n        result=\\\"allow\\\",\\n        details={\\n            # The guard already wrote an ``event: authorization_decision`` row\\n            # for the share:create check. This row is the effect, and only it\\n            # means a share now exists.\\n            \\\"event\\\": AUDIT_EVENT_MUTATION,\\n            \\\"share_id\\\": str(response.id),\\n            \\\"scope\\\": payload.scope,\\n            \\\"target_id\\\": str(payload.target_id) if payload.target_id else None,\\n            \\\"permission_level\\\": payload.permission_level,\\n        },\\n    )\\n    return response\\n\\n\\n_LIST_SHARES_MAX_LIMIT = 200\\n_LIST_SHARES_DEFAULT_LIMIT = 100\\n\\n\\n@router.get(\\\"\\\", response_model=list[ShareRead])\\n@router.get(\\\"/\\\", response_model=list[ShareRead])\\nasync def list_shares(\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    resource_type: Annotated[str | None, Query()] = None,\\n    resource_id: Annotated[UUID | None, Query()] = None,\\n    target_id: Annotated[UUID | None, Query()] = None,\\n    scope: Annotated[str | None, Query()] = None,\\n    limit: Annotated[int, Query(ge=1, le=_LIST_SHARES_MAX_LIMIT)] = _LIST_SHARES_DEFAULT_LIMIT,\\n    offset: Annotated[int, Query(ge=0)] = 0,\\n) -> list[ShareRead]:\\n    \\\"\\\"\\\"List share rows visible to the caller (paginated, max 200).\\\"\\\"\\\"\\n    await ensure_share_permission(\\n        current_user,\\n        ShareAction.READ,\\n        share_user_id=current_user.id,\\n    )\\n\\n    stmt = select(AuthzShare)\\n    if resource_type is not None:\\n        stmt = stmt.where(AuthzShare.resource_type == resource_type)\\n    if resource_id is not None:\\n        stmt = stmt.where(AuthzShare.resource_id == resource_id)\\n    if target_id is not None:\\n        stmt = stmt.where(AuthzShare.target_id == target_id)\\n    if scope is not None:\\n        # Reject unknown scope values early (422).\\n        try:\\n            scope_value = ShareScope(scope).value\\n        except ValueError as exc:\\n            raise HTTPException(status_code=400, detail=f\\\"Unknown scope {scope!r}\\\") from exc\\n        stmt = stmt.where(AuthzShare.scope == scope_value)\\n\\n    # Stable ordering with offset/limit pagination.\\n    stmt = stmt.order_by(AuthzShare.created_at.desc(), AuthzShare.id).offset(offset).limit(limit)\\n\\n    rows = list(await session.exec(stmt))\\n\\n    is_superuser = getattr(current_user, \\\"is_superuser\\\", False)\\n    if is_superuser:\\n        return await _serialize_shares(session, rows)\\n\\n    # Pre-fetch team memberships (avoid N+1 per row).\\n    team_membership_stmt = _active_team_ids_for_user(current_user.id)\\n    caller_team_ids: set[UUID] = set(await session.exec(team_membership_stmt))\\n\\n    # Filter rows by visibility rules for non-superusers.\\n    visible: list[AuthzShare] = []\\n    owner_cache: dict[tuple[str, UUID], UUID | None] = {}\\n    for row in rows:\\n        key = (row.resource_type, row.resource_id)\\n        if key not in owner_cache:\\n            owner_cache[key] = await _resolve_resource_owner(\\n                session,\\n                resource_type=row.resource_type,\\n                resource_id=row.resource_id,\\n            )\\n        if _row_visible_to(\\n            row=row,\\n            user_id=current_user.id,\\n            resource_owner_id=owner_cache[key],\\n            caller_team_ids=caller_team_ids,\\n        ):\\n            visible.append(row)\\n    return await _serialize_shares(session, visible)\\n\\n\\ndef _row_visible_to(\\n    *,\\n    row: AuthzShare,\\n    user_id: UUID,\\n    resource_owner_id: UUID | None,\\n    caller_team_ids: set[UUID],\\n) -> bool:\\n    \\\"\\\"\\\"Batch list visibility check using pre-fetched team ids.\\\"\\\"\\\"\\n    is_team_member = row.target_id is not None and row.target_id in caller_team_ids\\n    return _share_visible(\\n        row=row,\\n        user_id=user_id,\\n        resource_owner_id=resource_owner_id,\\n        is_team_member=is_team_member,\\n    )\\n\\n\\n@router.get(\\\"/{share_id}\\\", response_model=ShareRead)\\nasync def get_share(\\n    share_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> ShareRead:\\n    \\\"\\\"\\\"Fetch a single share by id with the same visibility rules as list.\\\"\\\"\\\"\\n    row = await session.get(AuthzShare, share_id)\\n    if row is None:\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Share not found\\\")\\n\\n    owner_id = await _resolve_resource_owner(\\n        session,\\n        resource_type=row.resource_type,\\n        resource_id=row.resource_id,\\n    )\\n    # See create_share: owner_id is the *resource* owner so non-owners are\\n    # forced through ensure_share_permission's plugin enforce() path.\\n    await ensure_share_permission(\\n        current_user,\\n        ShareAction.READ,\\n        share_id=share_id,\\n        share_user_id=owner_id,\\n    )\\n\\n    if not getattr(current_user, \\\"is_superuser\\\", False) and not await _user_can_see_share(\\n        session,\\n        row=row,\\n        user_id=current_user.id,\\n        resource_owner_id=owner_id,\\n    ):\\n        # UUID privacy: forbidden share \u2192 404.\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Share not found\\\")\\n\\n    return (await _serialize_shares(session, [row]))[0]\\n\\n\\n@router.patch(\\\"/{share_id}\\\", response_model=ShareRead)\\nasync def update_share(\\n    share_id: UUID,\\n    payload: ShareUpdate,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> ShareRead:\\n    \\\"\\\"\\\"Update the permission level of an existing share.\\\"\\\"\\\"\\n    row = await session.get(AuthzShare, share_id)\\n    if row is None:\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Share not found\\\")\\n\\n    owner_id = await _resolve_resource_owner(\\n        session,\\n        resource_type=row.resource_type,\\n        resource_id=row.resource_id,\\n    )\\n    await _ensure_can_administer_share(user=current_user, owner_id=owner_id)\\n    # See create_share: owner_id is the *resource* owner so non-owners are\\n    # forced through ensure_share_permission's plugin enforce() path.\\n    await ensure_share_permission(\\n        current_user,\\n        ShareAction.UPDATE,\\n        share_id=share_id,\\n        share_user_id=owner_id,\\n    )\\n    _ensure_supported_share_permission(\\n        resource_type=row.resource_type,\\n        scope=row.scope,\\n        permission_level=payload.permission_level,\\n    )\\n\\n    # Validate permission_level (422 before DB CHECK).\\n    try:\\n        row.permission_level = SharePermissionLevel(payload.permission_level).value\\n    except ValueError as exc:\\n        raise HTTPException(\\n            status_code=400,\\n            detail=f\\\"Unknown permission_level {payload.permission_level!r}\\\",\\n        ) from exc\\n    session.add(row)\\n    # Rollback + fixed 409 on constraint failure (same as create_share).\\n    try:\\n        await session.flush()\\n    except Exception as exc:\\n        await session.rollback()\\n        logger.warning(\\\"authz_share update rejected: %s\\\", exc)\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=\\\"Share could not be updated: it may conflict with an existing share.\\\",\\n        ) from exc\\n    await session.refresh(row)\\n    response = (await _serialize_shares(session, [row]))[0]\\n    await session.commit()\\n\\n    await _refresh_policy_for_share(response.id, response.scope, response.target_id, op=\\\"share:update\\\")\\n\\n    await audit_decision(\\n        user_id=current_user.id,\\n        action=\\\"share:update\\\",\\n        obj=f\\\"{response.resource_type}:{response.resource_id}\\\",\\n        result=\\\"allow\\\",\\n        details={\\n            \\\"event\\\": AUDIT_EVENT_MUTATION,\\n            \\\"share_id\\\": str(response.id),\\n            \\\"permission_level\\\": response.permission_level,\\n        },\\n    )\\n    return response\\n\\n\\n@router.delete(\\\"/{share_id}\\\", status_code=status.HTTP_204_NO_CONTENT)\\nasync def delete_share(\\n    share_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> None:\\n    \\\"\\\"\\\"Revoke an existing share.\\\"\\\"\\\"\\n    row = await session.get(AuthzShare, share_id)\\n    if row is None:\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Share not found\\\")\\n\\n    owner_id = await _resolve_resource_owner(\\n        session,\\n        resource_type=row.resource_type,\\n        resource_id=row.resource_id,\\n    )\\n    await _ensure_can_administer_share(user=current_user, owner_id=owner_id)\\n    # See create_share: owner_id is the *resource* owner so non-owners are\\n    # forced through ensure_share_permission's plugin enforce() path.\\n    await ensure_share_permission(\\n        current_user,\\n        ShareAction.DELETE,\\n        share_id=share_id,\\n        share_user_id=owner_id,\\n    )\\n\\n    snapshot = ShareRuleSnapshot(\\n        share_id=row.id,\\n        resource_type=row.resource_type,\\n        resource_id=row.resource_id,\\n        scope=row.scope,\\n        target_id=row.target_id,\\n        permission_level=row.permission_level,\\n    )\\n    await session.delete(row)\\n    await session.flush()\\n    await session.commit()\\n\\n    await _remove_policy_for_share(snapshot, op=\\\"share:delete\\\")\\n\\n    await audit_decision(\\n        user_id=current_user.id,\\n        action=\\\"share:delete\\\",\\n        obj=f\\\"{snapshot.resource_type}:{snapshot.resource_id}\\\",\\n        result=\\\"allow\\\",\\n        details={\\\"event\\\": AUDIT_EVENT_MUTATION, \\\"share_id\\\": str(share_id)},\\n    )\\n\\n\\n__all__ = [\\\"router\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/authz_teams.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c9a8fa8bc2f871cb7f9d41b8376580e80afe8cd0fafc995147f2735fdd55f4c6\",\"content\":\"\\\"\\\"\\\"CRUD API for authz_team and authz_team_member rows.\\n\\nTeams group users for bulk role assignment and share targeting. The\\nauthorization plugin compiles team memberships into its own representation\\nduring policy sync.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timezone\\nfrom typing import Annotated\\nfrom uuid import UUID\\n\\nfrom fastapi import APIRouter, Depends, HTTPException, Query, Request, status\\nfrom lfx.log.logger import logger\\nfrom lfx.services.authorization import AuthorizationMutation, AuthorizationMutationKind\\nfrom lfx.utils.util_strings import escape_like_pattern\\nfrom sqlalchemy.exc import IntegrityError\\nfrom sqlmodel import select\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSession\\nfrom langflow.api.v1.schemas.authz_teams import (\\n    TeamCreate,\\n    TeamMemberCreate,\\n    TeamMemberRead,\\n    TeamRead,\\n    TeamUpdate,\\n)\\nfrom langflow.services.authorization.audit import AUDIT_EVENT_ACCESS, AUDIT_EVENT_MUTATION\\nfrom langflow.services.authorization.lifecycle import (\\n    acquire_identity_mutation_lock,\\n    safe_identity_mutation_committed,\\n    stage_identity_mutation,\\n)\\nfrom langflow.services.authorization.utils import audit_decision\\nfrom langflow.services.database.models.auth import AuthzTeam, AuthzTeamMember\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import get_authorization_service\\n\\nrouter = APIRouter(prefix=\\\"/authz/teams\\\", tags=[\\\"Authorization\\\"], include_in_schema=False)\\n\\n# See ``authz_roles._LIST_MAX_LIMIT`` \u2014 same bound, applied to teams + members.\\n_LIST_MAX_LIMIT = 200\\n_LIST_DEFAULT_LIMIT = 100\\n\\n\\nasync def _audit_deny(*, user_id: UUID, action: str, obj: str, status_code: int, reason: str) -> None:\\n    await audit_decision(\\n        user_id=user_id,\\n        action=action,\\n        obj=obj,\\n        result=\\\"deny\\\",\\n        details={\\\"event\\\": AUDIT_EVENT_ACCESS, \\\"status_code\\\": status_code, \\\"reason\\\": reason},\\n    )\\n\\n\\nasync def _require_superuser(user, *, action: str, obj: str) -> None:\\n    if not getattr(user, \\\"is_superuser\\\", False):\\n        await _audit_deny(\\n            user_id=user.id,\\n            action=action,\\n            obj=obj,\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            reason=\\\"superuser_required\\\",\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=\\\"Superuser required to administer teams.\\\",\\n        )\\n\\n\\nasync def _require_superuser_dependency(request: Request, current_user: CurrentActiveUser) -> None:\\n    \\\"\\\"\\\"Run the superuser gate as a route dependency, i.e. before body validation.\\n\\n    FastAPI solves a route's ``dependencies`` before validating that route's own\\n    body, so an unauthorised caller is refused whatever they post. Gated only in\\n    the endpoint body, they first receive the same 422 field names and enum\\n    values a superuser would, which lets them map the request contract of a\\n    route they cannot invoke.\\n\\n    The in-body call is kept as well: it is the gate for anything that reaches\\n    the endpoint function without FastAPI resolving dependencies.\\n    \\\"\\\"\\\"\\n    team_id = request.path_params.get(\\\"team_id\\\", \\\"*\\\")\\n    is_member_route = \\\"/members\\\" in request.url.path\\n    action = (\\n        \\\"team_member:create\\\"\\n        if is_member_route and request.method == \\\"POST\\\"\\n        else \\\"team_member:delete\\\"\\n        if is_member_route and request.method == \\\"DELETE\\\"\\n        else {\\\"POST\\\": \\\"team:create\\\", \\\"PATCH\\\": \\\"team:update\\\", \\\"DELETE\\\": \\\"team:delete\\\"}.get(\\n            request.method,\\n            \\\"team:access\\\",\\n        )\\n    )\\n    await _require_superuser(current_user, action=action, obj=f\\\"team:{team_id}\\\")\\n\\n\\nSUPERUSER_ONLY = [Depends(_require_superuser_dependency)]\\n\\n\\n# --- teams ---------------------------------------------------------------- #\\n\\n\\n@router.get(\\\"\\\", response_model=list[TeamRead])\\n@router.get(\\\"/\\\", response_model=list[TeamRead])\\nasync def list_teams(\\n    session: DbSession,\\n    current_user: CurrentActiveUser,  # noqa: ARG001 \u2014 any authenticated user can list\\n    search: Annotated[str | None, Query(description=\\\"Substring match on team_name or adom_name\\\")] = None,\\n    is_active: Annotated[bool | None, Query()] = None,\\n    limit: Annotated[int, Query(ge=1, le=_LIST_MAX_LIMIT)] = _LIST_DEFAULT_LIMIT,\\n    offset: Annotated[int, Query(ge=0)] = 0,\\n) -> list[TeamRead]:\\n    \\\"\\\"\\\"List teams. Open to any authenticated user (for the share dialog's team picker).\\n\\n    Paginated via ``limit`` / ``offset`` so a single call cannot enumerate every\\n    team. Stable order is ``(team_name, id)`` so ``offset`` is deterministic.\\n    \\\"\\\"\\\"\\n    stmt = select(AuthzTeam)\\n    if search:\\n        like = f\\\"%{escape_like_pattern(search)}%\\\"\\n        stmt = stmt.where(\\n            (AuthzTeam.team_name.ilike(like, escape=\\\"\\\\\\\\\\\")) | (AuthzTeam.adom_name.ilike(like, escape=\\\"\\\\\\\\\\\"))\\n        )\\n    if is_active is not None:\\n        stmt = stmt.where(AuthzTeam.is_active == is_active)\\n    stmt = stmt.order_by(AuthzTeam.team_name, AuthzTeam.id).offset(offset).limit(limit)\\n    rows = (await session.exec(stmt)).all()\\n    return [TeamRead.model_validate(row) for row in rows]\\n\\n\\n@router.get(\\\"/{team_id}\\\", response_model=TeamRead)\\nasync def read_team(\\n    team_id: UUID,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,  # noqa: ARG001\\n) -> TeamRead:\\n    team = await session.get(AuthzTeam, team_id)\\n    if team is None:\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Team not found\\\")\\n    return TeamRead.model_validate(team)\\n\\n\\n@router.post(\\\"\\\", response_model=TeamRead, status_code=status.HTTP_201_CREATED, dependencies=SUPERUSER_ONLY)\\n@router.post(\\\"/\\\", response_model=TeamRead, status_code=status.HTTP_201_CREATED, dependencies=SUPERUSER_ONLY)\\nasync def create_team(\\n    payload: TeamCreate,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> TeamRead:\\n    await _require_superuser(current_user, action=\\\"team:create\\\", obj=\\\"team:*\\\")\\n    authorization_service = get_authorization_service()\\n    await acquire_identity_mutation_lock(\\n        authorization_service,\\n        session,\\n        kind=AuthorizationMutationKind.TEAM_CREATED,\\n    )\\n    team = AuthzTeam(\\n        team_name=payload.team_name,\\n        adom_name=payload.adom_name,\\n        description=payload.description,\\n        is_active=payload.is_active,\\n    )\\n    session.add(team)\\n    mutation = AuthorizationMutation(\\n        kind=AuthorizationMutationKind.TEAM_CREATED,\\n        entity_id=team.id,\\n        actor_user_id=current_user.id,\\n        team_id=team.id,\\n        policy_relevant_fields=(\\\"adom_name\\\", \\\"is_active\\\"),\\n    )\\n    try:\\n        await session.flush()\\n        await stage_identity_mutation(authorization_service, session, mutation)\\n        await session.commit()\\n    except IntegrityError as exc:\\n        await session.rollback()\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"team:create\\\",\\n            obj=\\\"team:*\\\",\\n            status_code=status.HTTP_409_CONFLICT,\\n            reason=\\\"team_slug_conflict\\\",\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=f\\\"Team with adom_name {payload.adom_name!r} already exists\\\",\\n        ) from exc\\n    await safe_identity_mutation_committed(authorization_service, mutation)\\n    await session.refresh(team)\\n    await audit_decision(\\n        user_id=current_user.id,\\n        action=\\\"team:create\\\",\\n        obj=f\\\"team:{team.id}\\\",\\n        result=\\\"allow\\\",\\n        details={\\n            \\\"event\\\": AUDIT_EVENT_MUTATION,\\n            \\\"team_name\\\": team.team_name,\\n            \\\"adom_name\\\": team.adom_name,\\n        },\\n    )\\n    logger.info(\\\"Created team %s (id=%s)\\\", team.team_name, team.id)\\n    return TeamRead.model_validate(team)\\n\\n\\n@router.patch(\\\"/{team_id}\\\", response_model=TeamRead, dependencies=SUPERUSER_ONLY)\\nasync def update_team(\\n    team_id: UUID,\\n    payload: TeamUpdate,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> TeamRead:\\n    await _require_superuser(current_user, action=\\\"team:update\\\", obj=f\\\"team:{team_id}\\\")\\n    authorization_service = get_authorization_service()\\n    await acquire_identity_mutation_lock(\\n        authorization_service,\\n        session,\\n        kind=AuthorizationMutationKind.TEAM_UPDATED,\\n        entity_id=team_id,\\n    )\\n    team = await session.get(AuthzTeam, team_id)\\n    if team is None:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"team:update\\\",\\n            obj=f\\\"team:{team_id}\\\",\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            reason=\\\"team_not_found\\\",\\n        )\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Team not found\\\")\\n\\n    changed_fields: list[str] = []\\n    previous_adom_name = team.adom_name\\n    if payload.team_name is not None and team.team_name != payload.team_name:\\n        team.team_name = payload.team_name\\n        changed_fields.append(\\\"team_name\\\")\\n    if payload.adom_name is not None and team.adom_name != payload.adom_name:\\n        team.adom_name = payload.adom_name\\n        changed_fields.append(\\\"adom_name\\\")\\n    # description is nullable on the DB side, so use a presence check\\n    # (model_fields_set) instead of ``is not None`` \u2014 an explicit \\\"description\\\":\\n    # null in the body clears the field, while omitting it leaves the row alone.\\n    if \\\"description\\\" in payload.model_fields_set and team.description != payload.description:\\n        team.description = payload.description\\n        changed_fields.append(\\\"description\\\")\\n    if payload.is_active is not None and team.is_active != payload.is_active:\\n        team.is_active = payload.is_active\\n        changed_fields.append(\\\"is_active\\\")\\n    team.updated_at = datetime.now(timezone.utc)\\n    mutation = AuthorizationMutation(\\n        kind=AuthorizationMutationKind.TEAM_UPDATED,\\n        entity_id=team.id,\\n        actor_user_id=current_user.id,\\n        team_id=team.id,\\n        policy_relevant_fields=tuple(sorted(set(changed_fields) & {\\\"adom_name\\\", \\\"is_active\\\"})),\\n        previous_identifier=previous_adom_name if team.adom_name != previous_adom_name else None,\\n    )\\n    try:\\n        await session.flush()\\n        await stage_identity_mutation(authorization_service, session, mutation)\\n        await session.commit()\\n    except IntegrityError as exc:\\n        await session.rollback()\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"team:update\\\",\\n            obj=f\\\"team:{team_id}\\\",\\n            status_code=status.HTTP_409_CONFLICT,\\n            reason=\\\"team_slug_conflict\\\",\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=\\\"adom_name conflict \u2014 another team already uses this slug\\\",\\n        ) from exc\\n    await safe_identity_mutation_committed(authorization_service, mutation)\\n    await session.refresh(team)\\n    await audit_decision(\\n        user_id=current_user.id,\\n        action=\\\"team:update\\\",\\n        obj=f\\\"team:{team.id}\\\",\\n        result=\\\"allow\\\",\\n        details={\\n            \\\"event\\\": AUDIT_EVENT_MUTATION,\\n            \\\"team_name\\\": team.team_name,\\n            \\\"fields_changed\\\": sorted(changed_fields),\\n        },\\n    )\\n    logger.info(\\\"Updated team %s (id=%s)\\\", team.team_name, team.id)\\n    return TeamRead.model_validate(team)\\n\\n\\n@router.delete(\\\"/{team_id}\\\", status_code=status.HTTP_204_NO_CONTENT, dependencies=SUPERUSER_ONLY)\\nasync def delete_team(\\n    team_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> None:\\n    await _require_superuser(current_user, action=\\\"team:delete\\\", obj=f\\\"team:{team_id}\\\")\\n    authorization_service = get_authorization_service()\\n    await acquire_identity_mutation_lock(\\n        authorization_service,\\n        session,\\n        kind=AuthorizationMutationKind.TEAM_DELETED,\\n        entity_id=team_id,\\n    )\\n    team = await session.get(AuthzTeam, team_id)\\n    if team is None:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"team:delete\\\",\\n            obj=f\\\"team:{team_id}\\\",\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            reason=\\\"team_not_found\\\",\\n        )\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Team not found\\\")\\n    team_name = team.team_name\\n    mutation = AuthorizationMutation(\\n        kind=AuthorizationMutationKind.TEAM_DELETED,\\n        entity_id=team_id,\\n        actor_user_id=current_user.id,\\n        team_id=team_id,\\n        policy_relevant_fields=(\\\"adom_name\\\", \\\"is_active\\\"),\\n        previous_identifier=team.adom_name,\\n    )\\n    # Cascade on team_members handles cleanup; share rows targeting this team\\n    # are left in place (caller may want to migrate them before deleting).\\n    await session.delete(team)\\n    await session.flush()\\n    await stage_identity_mutation(authorization_service, session, mutation)\\n    await session.commit()\\n    await safe_identity_mutation_committed(authorization_service, mutation)\\n    await audit_decision(\\n        user_id=current_user.id,\\n        action=\\\"team:delete\\\",\\n        obj=f\\\"team:{team_id}\\\",\\n        result=\\\"allow\\\",\\n        details={\\\"event\\\": AUDIT_EVENT_MUTATION, \\\"team_name\\\": team_name},\\n    )\\n    logger.info(\\\"Deleted team id=%s\\\", team_id)\\n\\n\\n# --- team members --------------------------------------------------------- #\\n\\n\\n@router.get(\\\"/{team_id}/members\\\", response_model=list[TeamMemberRead])\\nasync def list_members(\\n    team_id: UUID,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,  # noqa: ARG001\\n    limit: Annotated[int, Query(ge=1, le=_LIST_MAX_LIMIT)] = _LIST_DEFAULT_LIMIT,\\n    offset: Annotated[int, Query(ge=0)] = 0,\\n) -> list[TeamMemberRead]:\\n    \\\"\\\"\\\"List members of a team. Any authenticated user (so the UI can render team rosters).\\n\\n    Paginated via ``limit`` / ``offset`` so a single call cannot enumerate a\\n    large team's full roster. Stable order is ``(created_at, user_id)``.\\n    \\\"\\\"\\\"\\n    team = await session.get(AuthzTeam, team_id)\\n    if team is None:\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Team not found\\\")\\n    stmt = (\\n        select(AuthzTeamMember)\\n        .where(AuthzTeamMember.team_id == team_id)\\n        .order_by(AuthzTeamMember.created_at, AuthzTeamMember.user_id)\\n        .offset(offset)\\n        .limit(limit)\\n    )\\n    rows = (await session.exec(stmt)).all()\\n    return [TeamMemberRead.model_validate(row) for row in rows]\\n\\n\\n@router.post(\\n    \\\"/{team_id}/members\\\",\\n    response_model=TeamMemberRead,\\n    status_code=status.HTTP_201_CREATED,\\n    dependencies=SUPERUSER_ONLY,\\n)\\nasync def add_member(\\n    team_id: UUID,\\n    payload: TeamMemberCreate,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> TeamMemberRead:\\n    await _require_superuser(current_user, action=\\\"team_member:create\\\", obj=f\\\"team:{team_id}\\\")\\n    authorization_service = get_authorization_service()\\n    await acquire_identity_mutation_lock(\\n        authorization_service,\\n        session,\\n        kind=AuthorizationMutationKind.TEAM_MEMBER_ADDED,\\n        affected_user_ids=(payload.user_id,),\\n    )\\n    team = await session.get(AuthzTeam, team_id)\\n    if team is None:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"team_member:create\\\",\\n            obj=f\\\"team:{team_id}\\\",\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            reason=\\\"team_not_found\\\",\\n        )\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Team not found\\\")\\n    user = await session.get(User, payload.user_id)\\n    if user is None:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"team_member:create\\\",\\n            obj=f\\\"team:{team_id}\\\",\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            reason=\\\"user_not_found\\\",\\n        )\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"user_id not found\\\")\\n\\n    member = AuthzTeamMember(\\n        team_id=team_id,\\n        user_id=payload.user_id,\\n        source=payload.source,\\n    )\\n    session.add(member)\\n    mutation = AuthorizationMutation(\\n        kind=AuthorizationMutationKind.TEAM_MEMBER_ADDED,\\n        entity_id=member.id,\\n        actor_user_id=current_user.id,\\n        affected_user_ids=(payload.user_id,),\\n        team_id=team_id,\\n        policy_relevant_fields=(\\\"team_id\\\", \\\"user_id\\\", \\\"source\\\"),\\n    )\\n    try:\\n        await session.flush()\\n        await stage_identity_mutation(authorization_service, session, mutation)\\n        await session.commit()\\n    except IntegrityError as exc:\\n        await session.rollback()\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"team_member:create\\\",\\n            obj=f\\\"team:{team_id}\\\",\\n            status_code=status.HTTP_409_CONFLICT,\\n            reason=\\\"membership_already_exists\\\",\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=\\\"User is already a member of this team\\\",\\n        ) from exc\\n    await safe_identity_mutation_committed(authorization_service, mutation)\\n    await session.refresh(member)\\n    await audit_decision(\\n        user_id=current_user.id,\\n        action=\\\"team_member:create\\\",\\n        obj=f\\\"team:{team_id}\\\",\\n        result=\\\"allow\\\",\\n        details={\\n            \\\"event\\\": AUDIT_EVENT_MUTATION,\\n            \\\"team_name\\\": team.team_name,\\n            \\\"user_id\\\": str(payload.user_id),\\n            \\\"source\\\": payload.source,\\n        },\\n    )\\n    logger.info(\\\"Added user=%s to team=%s\\\", payload.user_id, team_id)\\n    return TeamMemberRead.model_validate(member)\\n\\n\\n@router.delete(\\n    \\\"/{team_id}/members/{user_id}\\\",\\n    status_code=status.HTTP_204_NO_CONTENT,\\n    dependencies=SUPERUSER_ONLY,\\n)\\nasync def remove_member(\\n    team_id: UUID,\\n    user_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> None:\\n    await _require_superuser(current_user, action=\\\"team_member:delete\\\", obj=f\\\"team:{team_id}\\\")\\n    authorization_service = get_authorization_service()\\n    await acquire_identity_mutation_lock(\\n        authorization_service,\\n        session,\\n        kind=AuthorizationMutationKind.TEAM_MEMBER_REMOVED,\\n        affected_user_ids=(user_id,),\\n    )\\n    member = (\\n        await session.exec(\\n            select(AuthzTeamMember).where(\\n                AuthzTeamMember.team_id == team_id,\\n                AuthzTeamMember.user_id == user_id,\\n            )\\n        )\\n    ).first()\\n    if member is None:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"team_member:delete\\\",\\n            obj=f\\\"team:{team_id}\\\",\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            reason=\\\"membership_not_found\\\",\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            detail=\\\"Membership not found\\\",\\n        )\\n    mutation = AuthorizationMutation(\\n        kind=AuthorizationMutationKind.TEAM_MEMBER_REMOVED,\\n        entity_id=member.id,\\n        actor_user_id=current_user.id,\\n        affected_user_ids=(user_id,),\\n        team_id=team_id,\\n        policy_relevant_fields=(\\\"team_id\\\", \\\"user_id\\\", \\\"source\\\"),\\n    )\\n    await session.delete(member)\\n    await session.flush()\\n    await stage_identity_mutation(authorization_service, session, mutation)\\n    await session.commit()\\n    await safe_identity_mutation_committed(authorization_service, mutation)\\n    await audit_decision(\\n        user_id=current_user.id,\\n        action=\\\"team_member:delete\\\",\\n        obj=f\\\"team:{team_id}\\\",\\n        result=\\\"allow\\\",\\n        details={\\\"event\\\": AUDIT_EVENT_MUTATION, \\\"user_id\\\": str(user_id)},\\n    )\\n    logger.info(\\\"Removed user=%s from team=%s\\\", user_id, team_id)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"082c3253f899f580fefaa0ba2802739c1c97708e029a243bfb17628a979f0f6a\",\"content\":\"from lfx.template.frontend_node.base import FrontendNode\\nfrom pydantic import BaseModel, field_validator, model_serializer\\n\\n\\nclass CacheResponse(BaseModel):\\n    data: dict\\n\\n\\nclass Code(BaseModel):\\n    code: str\\n\\n\\nclass FrontendNodeRequest(FrontendNode):\\n    template: dict  # type: ignore[assignment]\\n\\n    @model_serializer(mode=\\\"wrap\\\")\\n    def serialize_model(self, handler):\\n        # Override the default serialization method in FrontendNode\\n        # because we don't need the name in the response (i.e. {name: {}})\\n        return handler(self)\\n\\n\\nclass ValidatePromptRequest(BaseModel):\\n    name: str\\n    template: str\\n    custom_fields: dict | None = None\\n    frontend_node: FrontendNodeRequest | None = None\\n    mustache: bool = False\\n\\n\\n# Build ValidationResponse class for {\\\"imports\\\": {\\\"errors\\\": []}, \\\"function\\\": {\\\"errors\\\": []}}\\nclass CodeValidationResponse(BaseModel):\\n    imports: dict\\n    function: dict\\n\\n    @field_validator(\\\"imports\\\")\\n    @classmethod\\n    def validate_imports(cls, v):\\n        return v or {\\\"errors\\\": []}\\n\\n    @field_validator(\\\"function\\\")\\n    @classmethod\\n    def validate_function(cls, v):\\n        return v or {\\\"errors\\\": []}\\n\\n\\nclass PromptValidationResponse(BaseModel):\\n    input_variables: list\\n    # object return for tweak call\\n    frontend_node: FrontendNodeRequest | None = None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/callback.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"75b9715da74b42b57e69f5a7999c175ffb34cceb67bef594f4b2e04f52183a1a\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import Any\\nfrom uuid import UUID\\n\\nfrom langchain_core.agents import AgentAction, AgentFinish\\nfrom langchain_core.callbacks.base import AsyncCallbackHandler\\nfrom lfx.log.logger import logger\\nfrom lfx.utils.util import remove_ansi_escape_codes\\nfrom typing_extensions import override\\n\\nfrom langflow.api.v1.schemas import ChatResponse, PromptResponse\\nfrom langflow.services.deps import get_chat_service\\n\\n\\n# https://github.com/hwchase17/chat-langchain/blob/master/callback.py\\nclass AsyncStreamingLLMCallbackHandleSIO(AsyncCallbackHandler):\\n    \\\"\\\"\\\"Callback handler for streaming LLM responses.\\\"\\\"\\\"\\n\\n    @property\\n    def ignore_chain(self) -> bool:\\n        \\\"\\\"\\\"Whether to ignore chain callbacks.\\\"\\\"\\\"\\n        return False\\n\\n    def __init__(self, session_id: str):\\n        self.chat_service = get_chat_service()\\n        self.client_id = session_id\\n        self.sid = session_id\\n\\n    @override\\n    async def on_llm_new_token(self, token: str, **kwargs: Any) -> None:  # type: ignore[misc]\\n        resp = ChatResponse(message=token, type=\\\"stream\\\", intermediate_steps=\\\"\\\")\\n        await self.socketio_service.emit_token(to=self.sid, data=resp.model_dump())\\n\\n    @override\\n    async def on_tool_start(self, serialized: dict[str, Any], input_str: str, **kwargs: Any) -> Any:  # type: ignore[misc]\\n        \\\"\\\"\\\"Run when tool starts running.\\\"\\\"\\\"\\n        resp = ChatResponse(\\n            message=\\\"\\\",\\n            type=\\\"stream\\\",\\n            intermediate_steps=f\\\"Tool input: {input_str}\\\",\\n        )\\n        await self.socketio_service.emit_token(to=self.sid, data=resp.model_dump())\\n\\n    async def on_tool_end(self, output: str, **kwargs: Any) -> Any:\\n        \\\"\\\"\\\"Run when tool ends running.\\\"\\\"\\\"\\n        observation_prefix = kwargs.get(\\\"observation_prefix\\\", \\\"Tool output: \\\")\\n        split_output = output.split()\\n        first_word = split_output[0]\\n        rest_of_output = split_output[1:]\\n        # Create a formatted message.\\n        intermediate_steps = f\\\"{observation_prefix}{first_word}\\\"\\n\\n        # Create a ChatResponse instance.\\n        resp = ChatResponse(\\n            message=\\\"\\\",\\n            type=\\\"stream\\\",\\n            intermediate_steps=intermediate_steps,\\n        )\\n        rest_of_resps = [\\n            ChatResponse(\\n                message=\\\"\\\",\\n                type=\\\"stream\\\",\\n                intermediate_steps=f\\\"{word}\\\",\\n            )\\n            for word in rest_of_output\\n        ]\\n        resps = [resp, *rest_of_resps]\\n        # Try to send the response, handle potential errors.\\n\\n        try:\\n            # This is to emulate the stream of tokens\\n            for resp in resps:\\n                await self.socketio_service.emit_token(to=self.sid, data=resp.model_dump())\\n        except Exception:  # noqa: BLE001\\n            await logger.aexception(\\\"Error sending response\\\")\\n\\n    async def on_tool_error(\\n        self,\\n        error: BaseException,\\n        *,\\n        run_id: UUID,\\n        parent_run_id: UUID | None = None,\\n        tags: list[str] | None = None,\\n        **kwargs: Any,\\n    ) -> None:\\n        \\\"\\\"\\\"Run when tool errors.\\\"\\\"\\\"\\n\\n    @override\\n    async def on_text(  # type: ignore[misc]\\n        self, text: str, **kwargs: Any\\n    ) -> Any:\\n        \\\"\\\"\\\"Run on arbitrary text.\\\"\\\"\\\"\\n        # This runs when first sending the prompt\\n        # to the LLM, adding it will send the final prompt\\n        # to the frontend\\n        if \\\"Prompt after formatting\\\" in text:\\n            text = text.replace(\\\"Prompt after formatting:\\\\n\\\", \\\"\\\")\\n            text = remove_ansi_escape_codes(text)\\n            resp = PromptResponse(\\n                prompt=text,\\n            )\\n            await self.socketio_service.emit_message(to=self.sid, data=resp.model_dump())\\n\\n    @override\\n    async def on_agent_action(  # type: ignore[misc]\\n        self, action: AgentAction, **kwargs: Any\\n    ) -> None:\\n        log = f\\\"Thought: {action.log}\\\"\\n        # if there are line breaks, split them and send them\\n        # as separate messages\\n        if \\\"\\\\n\\\" in log:\\n            logs = log.split(\\\"\\\\n\\\")\\n            for log in logs:\\n                resp = ChatResponse(message=\\\"\\\", type=\\\"stream\\\", intermediate_steps=log)\\n                await self.socketio_service.emit_token(to=self.sid, data=resp.model_dump())\\n        else:\\n            resp = ChatResponse(message=\\\"\\\", type=\\\"stream\\\", intermediate_steps=log)\\n            await self.socketio_service.emit_token(to=self.sid, data=resp.model_dump())\\n\\n    @override\\n    async def on_agent_finish(  # type: ignore[misc]\\n        self, finish: AgentFinish, **kwargs: Any\\n    ) -> Any:\\n        \\\"\\\"\\\"Run on agent end.\\\"\\\"\\\"\\n        resp = ChatResponse(\\n            message=\\\"\\\",\\n            type=\\\"stream\\\",\\n            intermediate_steps=finish.log,\\n        )\\n        await self.socketio_service.emit_token(to=self.sid, data=resp.model_dump())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/catalog_policy.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d20d2df959344a2c2b19c1438b5e19595370babe56bfca83f55c9a6e42d00fa0\",\"content\":\"\\\"\\\"\\\"Superuser administration API for global catalog block policy.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport time\\nfrom typing import TYPE_CHECKING, Annotated, Literal, NamedTuple\\nfrom uuid import UUID\\n\\nfrom fastapi import APIRouter, Depends, HTTPException, Query, status\\nfrom lfx.services.catalog_policy import BaseCatalogPolicyService, CatalogPolicySnapshot\\nfrom lfx.services.deps import session_scope_readonly\\nfrom lfx.utils.component_aliases import build_component_identity_index\\nfrom lfx.utils.flow_validation import collect_catalog_component_keys\\nfrom sqlmodel import col, select\\n\\nfrom langflow.api.v1.policy_bundle_errors import policy_bundle_revision_conflict\\nfrom langflow.api.v1.schemas.catalog_policy import (\\n    CATALOG_POLICY_KEY_MAX_LENGTH,\\n    CatalogPolicyBlockedSet,\\n    CatalogPolicyRead,\\n    CatalogPolicyUsageFlowRef,\\n    CatalogPolicyUsageFlowsRead,\\n    CatalogPolicyUsageRead,\\n)\\nfrom langflow.services.auth.utils import get_current_active_superuser\\nfrom langflow.services.authorization.audit import audit_decision\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import get_catalog_policy_service\\nfrom langflow.services.policy_bundle import PolicyBundleRevisionConflictError\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Sequence\\n\\n    from lfx.utils.component_aliases import ComponentIdentityIndex\\n\\nrouter = APIRouter(prefix=\\\"/catalog-policy\\\", tags=[\\\"Catalog Policy\\\"])\\n\\nUSAGE_FLOWS_DEFAULT_LIMIT = 100\\nUSAGE_FLOWS_MAX_LIMIT = 500\\n# How long one flow-table scan is reused by the usage endpoints. Governance\\n# counts may lag flow writes by up to this window; policy writes never change\\n# usage data, so a refetch after saving a policy is served from cache exactly.\\nUSAGE_SCAN_CACHE_TTL_SECONDS = 30.0\\n\\n\\ndef _active_snapshot(service: BaseCatalogPolicyService) -> tuple[CatalogPolicySnapshot, bool]:\\n    external_snapshot = service.external_policy_snapshot\\n    if external_snapshot is not None:\\n        return external_snapshot, True\\n    return service.snapshot, False\\n\\n\\ndef _response(blocked: frozenset[str], *, managed_externally: bool) -> CatalogPolicyRead:\\n    return CatalogPolicyRead(\\n        blocked=sorted(blocked),\\n        managed_externally=managed_externally,\\n    )\\n\\n\\ndef _raise_if_externally_managed(service: BaseCatalogPolicyService) -> None:\\n    if service.external_policy_snapshot is not None:\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=\\\"Catalog policy is externally managed and cannot be changed through this API.\\\",\\n        )\\n    if not service.supports_policy_bundle_updates:\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=(\\n                \\\"Configured catalog policy service does not support shared policy bundle updates; \\\"\\n                \\\"upgrade the plugin before changing database-backed policy\\\"\\n            ),\\n        )\\n\\n\\nasync def _audit_update(\\n    *,\\n    user_id: UUID,\\n    resource_kind: Literal[\\\"component\\\", \\\"template\\\"],\\n    added: frozenset[str],\\n    removed: frozenset[str],\\n) -> None:\\n    \\\"\\\"\\\"Emit one post-commit audit event per changed catalog key.\\\"\\\"\\\"\\n    for key in sorted(added):\\n        await audit_decision(\\n            user_id=user_id,\\n            action=\\\"catalog:block\\\",\\n            obj=f\\\"{resource_kind}:{key}\\\",\\n            result=\\\"allow\\\",\\n            details={\\n                \\\"resource_kind\\\": resource_kind,\\n                \\\"resource_key\\\": key,\\n            },\\n        )\\n    for key in sorted(removed):\\n        await audit_decision(\\n            user_id=user_id,\\n            action=\\\"catalog:unblock\\\",\\n            obj=f\\\"{resource_kind}:{key}\\\",\\n            result=\\\"allow\\\",\\n            details={\\n                \\\"resource_kind\\\": resource_kind,\\n                \\\"resource_key\\\": key,\\n            },\\n        )\\n\\n\\n@router.get(\\\"/components\\\", response_model=CatalogPolicyRead)\\nasync def get_component_policy(\\n    _admin: Annotated[User, Depends(get_current_active_superuser)],\\n) -> CatalogPolicyRead:\\n    \\\"\\\"\\\"Return the complete global component block set.\\\"\\\"\\\"\\n    service = get_catalog_policy_service()\\n    snapshot, managed_externally = _active_snapshot(service)\\n    return _response(snapshot.blocked_component_keys, managed_externally=managed_externally)\\n\\n\\n@router.put(\\\"/components\\\", response_model=CatalogPolicyRead)\\nasync def replace_component_policy(\\n    payload: CatalogPolicyBlockedSet,\\n    admin: Annotated[User, Depends(get_current_active_superuser)],\\n) -> CatalogPolicyRead:\\n    \\\"\\\"\\\"Replace the complete global component block set.\\\"\\\"\\\"\\n    service = get_catalog_policy_service()\\n    _raise_if_externally_managed(service)\\n    try:\\n        update = await service.replace_blocked_component_keys(\\n            payload.blocked,\\n            actor_user_id=admin.id,\\n        )\\n    except PolicyBundleRevisionConflictError as exc:\\n        raise policy_bundle_revision_conflict(exc) from exc\\n    await _audit_update(\\n        user_id=admin.id,\\n        resource_kind=\\\"component\\\",\\n        added=update.added,\\n        removed=update.removed,\\n    )\\n    return _response(update.snapshot.blocked_component_keys, managed_externally=False)\\n\\n\\n@router.get(\\\"/templates\\\", response_model=CatalogPolicyRead)\\nasync def get_template_policy(\\n    _admin: Annotated[User, Depends(get_current_active_superuser)],\\n) -> CatalogPolicyRead:\\n    \\\"\\\"\\\"Return the complete global template block set.\\\"\\\"\\\"\\n    service = get_catalog_policy_service()\\n    snapshot, managed_externally = _active_snapshot(service)\\n    return _response(snapshot.blocked_template_keys, managed_externally=managed_externally)\\n\\n\\n@router.put(\\\"/templates\\\", response_model=CatalogPolicyRead)\\nasync def replace_template_policy(\\n    payload: CatalogPolicyBlockedSet,\\n    admin: Annotated[User, Depends(get_current_active_superuser)],\\n) -> CatalogPolicyRead:\\n    \\\"\\\"\\\"Replace the complete global template block set.\\\"\\\"\\\"\\n    service = get_catalog_policy_service()\\n    _raise_if_externally_managed(service)\\n    try:\\n        update = await service.replace_blocked_template_keys(\\n            payload.blocked,\\n            actor_user_id=admin.id,\\n        )\\n    except PolicyBundleRevisionConflictError as exc:\\n        raise policy_bundle_revision_conflict(exc) from exc\\n    await _audit_update(\\n        user_id=admin.id,\\n        resource_kind=\\\"template\\\",\\n        added=update.added,\\n        removed=update.removed,\\n    )\\n    return _response(update.snapshot.blocked_template_keys, managed_externally=False)\\n\\n\\nclass _FlowUsage(NamedTuple):\\n    \\\"\\\"\\\"One flow's identity, display name, and exact stored component keys.\\\"\\\"\\\"\\n\\n    flow_id: UUID\\n    name: str\\n    component_keys: frozenset[str]\\n\\n\\nasync def _load_flow_component_usage() -> tuple[list[_FlowUsage], int]:\\n    \\\"\\\"\\\"Return per-flow component keys and the total number of flows scanned.\\n\\n    Saved components (``is_component``) are excluded \u2014 they are palette\\n    entries, not flows. Every remaining flow's stored graph is scanned,\\n    including nested flows inlined in legacy Run Flow nodes. This reads each\\n    flow's full ``data`` payload, so it is reserved for the superuser\\n    governance endpoints below rather than any per-request path.\\n    \\\"\\\"\\\"\\n    async with session_scope_readonly() as session:\\n        rows = (\\n            await session.exec(\\n                select(Flow.id, Flow.name, Flow.data).where(\\n                    col(Flow.is_component).is_not(True),\\n                    col(Flow.data).is_not(None),\\n                )\\n            )\\n        ).all()\\n    usage = [\\n        _FlowUsage(flow_id=flow_id, name=name, component_keys=component_keys)\\n        for flow_id, name, data in rows\\n        if (component_keys := collect_catalog_component_keys(data))\\n    ]\\n    return usage, len(rows)\\n\\n\\nclass _UsageScan(NamedTuple):\\n    \\\"\\\"\\\"An immutable flow-table scan plus the monotonic instant it was taken.\\\"\\\"\\\"\\n\\n    usage: tuple[_FlowUsage, ...]\\n    flows_scanned: int\\n    loaded_at: float\\n\\n\\n_usage_scan_cache: _UsageScan | None = None\\n\\n\\nasync def _cached_flow_component_usage() -> tuple[Sequence[_FlowUsage], int]:\\n    \\\"\\\"\\\"Serve the flow scan from a short process-local cache.\\n\\n    Both usage endpoints share one scan per TTL window, so an admin page that\\n    fetches counts on mount and refetches after every policy save costs one\\n    flow-table read per window instead of one per request. There is\\n    deliberately no lock: concurrent cache misses each scan and the last\\n    writer wins, which only duplicates work an uncached implementation would\\n    do anyway. The cache is per-process; workers converge within one TTL.\\n    \\\"\\\"\\\"\\n    global _usage_scan_cache  # noqa: PLW0603 - module-level TTL cache\\n    cached = _usage_scan_cache\\n    if cached is not None and time.monotonic() - cached.loaded_at < USAGE_SCAN_CACHE_TTL_SECONDS:\\n        return cached.usage, cached.flows_scanned\\n    usage, flows_scanned = await _load_flow_component_usage()\\n    _usage_scan_cache = _UsageScan(\\n        usage=tuple(usage),\\n        flows_scanned=flows_scanned,\\n        loaded_at=time.monotonic(),\\n    )\\n    return usage, flows_scanned\\n\\n\\nasync def _usage_identity_index() -> ComponentIdentityIndex:\\n    \\\"\\\"\\\"Return the collision-aware identity index for the current registry.\\n\\n    Built from the same registry mapping the palette endpoint filters, so\\n    usage numbers match what catalog enforcement would actually block.\\n    \\\"\\\"\\\"\\n    from langflow.interface.components import get_and_cache_all_types_dict, get_component_identity_index\\n    from langflow.services.deps import get_settings_service\\n\\n    all_types = await get_and_cache_all_types_dict(settings_service=get_settings_service())\\n    index = get_component_identity_index(all_types)\\n    if index is None:\\n        # Only a None mapping can yield None; keep the type checker satisfied.\\n        index = build_component_identity_index(all_types)\\n    return index\\n\\n\\n@router.get(\\\"/usage\\\", response_model=CatalogPolicyUsageRead)\\nasync def get_component_usage(\\n    _admin: Annotated[User, Depends(get_current_active_superuser)],\\n) -> CatalogPolicyUsageRead:\\n    \\\"\\\"\\\"Return how many flows use each component.\\n\\n    Counts are keyed by canonical registry identity \u2014 a flow node saved under\\n    a legacy alias is counted under the component it resolves to today, the\\n    same resolution catalog enforcement applies. Keys not present in the\\n    registry (custom or synthetic components) are counted under their exact\\n    stored key. Each flow is counted at most once per component. Counts may\\n    lag flow writes by up to ``USAGE_SCAN_CACHE_TTL_SECONDS``.\\n    \\\"\\\"\\\"\\n    usage, flows_scanned = await _cached_flow_component_usage()\\n    identity_index = await _usage_identity_index()\\n\\n    counts: dict[str, int] = {}\\n    for flow in usage:\\n        for identity in identity_index.resolve_many(flow.component_keys):\\n            counts[identity] = counts.get(identity, 0) + 1\\n    return CatalogPolicyUsageRead(\\n        components=dict(sorted(counts.items())),\\n        flows_scanned=flows_scanned,\\n    )\\n\\n\\n@router.get(\\\"/usage/flows\\\", response_model=CatalogPolicyUsageFlowsRead)\\nasync def get_component_usage_flows(\\n    _admin: Annotated[User, Depends(get_current_active_superuser)],\\n    component: Annotated[\\n        str,\\n        Query(\\n            min_length=1,\\n            max_length=CATALOG_POLICY_KEY_MAX_LENGTH,\\n            description=\\\"Component key to look up; aliases resolve like catalog enforcement.\\\",\\n        ),\\n    ],\\n    limit: Annotated[int, Query(ge=1, le=USAGE_FLOWS_MAX_LIMIT)] = USAGE_FLOWS_DEFAULT_LIMIT,\\n) -> CatalogPolicyUsageFlowsRead:\\n    \\\"\\\"\\\"Return the flows that would be affected by blocking one component key.\\n\\n    A flow matches when the queried key and any of the flow's stored keys\\n    resolve to a shared canonical identity \u2014 the same matching rule flow\\n    writes and runs enforce. Flows are sorted by name, then id, and truncated\\n    to ``limit``; ``total`` always reports the full match count. Results may\\n    lag flow writes by up to ``USAGE_SCAN_CACHE_TTL_SECONDS``.\\n    \\\"\\\"\\\"\\n    component = component.strip()\\n    if not component:\\n        raise HTTPException(\\n            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,\\n            detail=\\\"component must not be blank\\\",\\n        )\\n    usage, _flows_scanned = await _cached_flow_component_usage()\\n    identity_index = await _usage_identity_index()\\n\\n    target_identities = identity_index.resolve(component)\\n    matches = [\\n        flow for flow in usage if not target_identities.isdisjoint(identity_index.resolve_many(flow.component_keys))\\n    ]\\n    matches.sort(key=lambda flow: (flow.name.casefold(), str(flow.flow_id)))\\n    return CatalogPolicyUsageFlowsRead(\\n        component=component,\\n        total=len(matches),\\n        flows=[CatalogPolicyUsageFlowRef(id=flow.flow_id, name=flow.name) for flow in matches[:limit]],\\n    )\\n\\n\\n__all__ = [\\\"router\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/chat.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a83a09227ef4e2c2b7c312ea8e2233c6841578f270e6d857cb019a87dec87034\",\"content\":\"from __future__ import annotations\\n\\nimport asyncio\\nimport time\\nimport traceback\\nimport uuid\\nfrom typing import TYPE_CHECKING, Annotated\\n\\nfrom fastapi import APIRouter, BackgroundTasks, Body, Depends, HTTPException, Request, status\\nfrom fastapi.responses import StreamingResponse\\nfrom lfx.exceptions.tweaks import TweakRefusedError\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.graph.utils import log_vertex_build\\nfrom lfx.log.logger import logger\\nfrom lfx.observability import execution_protocol\\nfrom lfx.schema.schema import InputValueRequest, OutputValue\\nfrom lfx.services.cache.utils import CacheMiss\\nfrom lfx.utils.flow_validation import (\\n    PUBLIC_CATALOG_POLICY_UNAVAILABLE_MESSAGE,\\n    CatalogPolicyIdentityUnavailableError,\\n    CustomComponentValidationError,\\n    prepare_flow_build_for_user,\\n    prepare_public_flow_build,\\n    validate_catalog_policy_for_flow,\\n    validate_flow_for_current_settings,\\n    validate_public_flow_no_code_execution,\\n)\\nfrom sqlmodel import select\\n\\nfrom langflow.api.build import cancel_flow_build, get_flow_events_response, start_flow_build\\nfrom langflow.api.limited_background_tasks import LimitVertexBuildBackgroundTasks\\nfrom langflow.api.utils import (\\n    CurrentActiveUser,\\n    DbSession,\\n    EventDeliveryType,\\n    build_and_cache_graph_from_data,\\n    build_graph_from_db,\\n    format_elapsed_time,\\n    format_exception_message,\\n    get_top_level_vertices,\\n    parse_exception,\\n    scope_session_to_namespace,\\n    validate_public_files,\\n    verify_public_flow_and_get_user,\\n)\\nfrom langflow.api.utils.core import strip_secret_field_values\\nfrom langflow.api.v1.schemas import (\\n    CancelFlowResponse,\\n    FlowDataRequest,\\n    ResultDataResponse,\\n    StreamData,\\n    VertexBuildResponse,\\n    VerticesOrderResponse,\\n)\\nfrom langflow.exceptions.component import ComponentBuildError\\nfrom langflow.services.auth.utils import get_current_user_optional\\nfrom langflow.services.authorization import FlowAction, ensure_flow_permission\\nfrom langflow.services.authorization.fetch import deny_to_404_unless_readable\\nfrom langflow.services.authorization.flow_data_override import resolve_flow_data_override\\nfrom langflow.services.authorization.public_access import (\\n    PUBLIC_FLOW_NOT_FOUND_DETAIL,\\n    PublicResourceAction,\\n    authorize_public_flow_access,\\n)\\nfrom langflow.services.chat.service import ChatService\\nfrom langflow.services.database.models.flow.model import AccessTypeEnum, Flow\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import (\\n    get_chat_service,\\n    get_queue_service,\\n    get_settings_service,\\n    get_telemetry_service,\\n    session_scope,\\n)\\nfrom langflow.services.job_queue.service import (\\n    JobQueueBackendUnavailableError,\\n    JobQueueNotFoundError,\\n    JobQueueService,\\n)\\nfrom langflow.services.model_provider_policy_scope import scoped_model_provider_policy_for_flow\\nfrom langflow.services.rate_limit import check_rate_limit\\nfrom langflow.services.telemetry.schema import ComponentPayload, PlaygroundPayload\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.vertex.vertex_types import InterfaceVertex\\n\\nrouter = APIRouter(tags=[\\\"Chat\\\"])\\n\\nFLOW_EXECUTE_DENIED_DETAIL = \\\"You don't have permission to execute this flow.\\\"\\n\\n\\ndef _validate_graph_for_execution(graph: Graph) -> None:\\n    \\\"\\\"\\\"Validate the effective cached graph against the current runtime policy.\\\"\\\"\\\"\\n    try:\\n        validate_flow_for_current_settings(graph)\\n    except CatalogPolicyIdentityUnavailableError as exc:\\n        raise HTTPException(status_code=503, detail=str(exc)) from exc\\n    except CustomComponentValidationError as exc:\\n        raise HTTPException(status_code=400, detail=str(exc)) from exc\\n    except RuntimeError as exc:\\n        raise HTTPException(status_code=503, detail=str(exc)) from exc\\n\\n\\nasync def _clear_invalid_graph_cache(chat_service: ChatService, flow_id: str) -> None:\\n    \\\"\\\"\\\"Best-effort eviction for a graph rejected by current runtime policy.\\\"\\\"\\\"\\n    try:\\n        await chat_service.clear_cache(flow_id)\\n    except Exception:  # noqa: BLE001\\n        await logger.aexception(\\\"Failed to evict a graph rejected by runtime policy\\\")\\n\\n\\nasync def _verify_job_ownership(job_id: str, current_user: CurrentActiveUser, queue_service: JobQueueService) -> None:\\n    \\\"\\\"\\\"Raise HTTP 404 if the requesting user does not own the job.\\n\\n    Jobs with no registered owner (build_public_tmp) are accessible to any authenticated user.\\n    \\\"\\\"\\\"\\n    try:\\n        job_owner = await queue_service.get_job_owner(job_id)\\n    except JobQueueBackendUnavailableError as exc:\\n        raise HTTPException(status_code=503, detail=str(exc)) from exc\\n    if job_owner is not None and job_owner != current_user.id:\\n        await logger.awarning(\\n            \\\"Ownership check failed: user %s tried to access job %s owned by %s\\\",\\n            current_user.id,\\n            job_id,\\n            job_owner,\\n        )\\n        raise HTTPException(status_code=404, detail=f\\\"Job not found: {job_id}\\\")\\n\\n\\nasync def _register_job_owner_or_cancel(queue_service: JobQueueService, job_id: str, user_id: uuid.UUID) -> None:\\n    \\\"\\\"\\\"Register the build's owner, cancelling the just-started build on backend outage.\\n\\n    By the time this runs, start_flow_build has already launched the build task.\\n    If the Redis-backed queue is unreachable, the client never receives the\\n    job_id, so cancel the build (best-effort) instead of leaving an unreachable\\n    build running, then surface a clean 503 instead of a raw redis\\n    ConnectionError 500.\\n    \\\"\\\"\\\"\\n    try:\\n        await queue_service.register_job_owner(job_id, user_id)\\n    except JobQueueBackendUnavailableError as exc:\\n        try:\\n            await queue_service.cancel_job(job_id)\\n        except Exception as cancel_exc:  # noqa: BLE001\\n            await logger.awarning(f\\\"Failed to cancel job {job_id} after owner registration failed: {cancel_exc!r}\\\")\\n        raise HTTPException(status_code=503, detail=str(exc)) from exc\\n\\n\\ndef _compiled_from(graph: object, graph_data: dict) -> bool:\\n    \\\"\\\"\\\"Whether this compilation was produced from exactly this payload.\\n\\n    ``raw_graph_data`` is part of ``Graph.__getstate__``, so this survives a serialized\\n    cache \u2014 a marker attribute would be dropped there and silently reintroduce the\\n    rebuild-per-request behaviour on Redis-backed deployments only.\\n    \\\"\\\"\\\"\\n    raw = getattr(graph, \\\"raw_graph_data\\\", None)\\n    if not isinstance(raw, dict):\\n        return False\\n    return raw.get(\\\"nodes\\\") == graph_data.get(\\\"nodes\\\") and raw.get(\\\"edges\\\") == graph_data.get(\\\"edges\\\")\\n\\n\\nasync def _trusted_stored_graph(flow_data, *, is_superuser: bool) -> dict | None:\\n    \\\"\\\"\\\"Run the caller-aware component policy over a STORED graph.\\n\\n    The stored graph is caller-controlled -- any user who can write a flow can persist\\n    component source through the ordinary flow API -- and the global validator does not\\n    know who is asking, so it cannot enforce ``custom_component_admin_only`` on its own.\\n    Returns the trusted copy to build from, or ``None`` when the policy is permissive and\\n    the stored graph stands. The status mapping matches the whole-flow build seam.\\n    \\\"\\\"\\\"\\n    try:\\n        return await prepare_flow_build_for_user(flow_data, is_superuser=is_superuser)\\n    except CatalogPolicyIdentityUnavailableError as exc:\\n        raise HTTPException(status_code=503, detail=str(exc)) from exc\\n    except CustomComponentValidationError as exc:\\n        raise HTTPException(status_code=400, detail=str(exc)) from exc\\n    except RuntimeError as exc:\\n        raise HTTPException(status_code=503, detail=str(exc)) from exc\\n\\n\\n@router.post(\\n    \\\"/build/{flow_id}/vertices\\\",\\n    deprecated=True,\\n    include_in_schema=False,\\n)\\nasync def retrieve_vertices_order(\\n    *,\\n    flow_id: uuid.UUID,\\n    background_tasks: BackgroundTasks,\\n    data: Annotated[FlowDataRequest | None, Body(embed=True)] | None = None,\\n    stop_component_id: str | None = None,\\n    start_component_id: str | None = None,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n) -> VerticesOrderResponse:\\n    \\\"\\\"\\\"Retrieve the vertices order for a given flow.\\n\\n    Args:\\n        flow_id (str): The ID of the flow.\\n        background_tasks (BackgroundTasks): The background tasks.\\n        data (Optional[FlowDataRequest], optional): The flow data. Defaults to None.\\n        stop_component_id (str, optional): The ID of the stop component. Defaults to None.\\n        start_component_id (str, optional): The ID of the start component. Defaults to None.\\n        session (AsyncSession, optional): The session dependency.\\n        current_user: The authenticated user (required so the handler can\\n            run the same authorization guard the supported /build/{flow_id}/flow\\n            route uses).\\n\\n    Returns:\\n        VerticesOrderResponse: The response containing the ordered vertex IDs and the run ID.\\n\\n    Raises:\\n        HTTPException: If there is an error checking the build status.\\n    \\\"\\\"\\\"\\n    # This deprecated editor route is owner-only. Supported full-flow routes\\n    # provide public execution without exposing the flow-keyed graph cache.\\n    stmt = select(Flow).where(Flow.id == flow_id).where(Flow.user_id == current_user.id)\\n    flow = (await session.exec(stmt)).first()\\n    if not flow:\\n        raise HTTPException(status_code=404, detail=f\\\"Flow with id {flow_id} not found\\\")\\n    await ensure_flow_permission(\\n        current_user,\\n        FlowAction.EXECUTE,\\n        flow_id=flow_id,\\n        flow_user_id=flow.user_id,\\n        workspace_id=flow.workspace_id,\\n        folder_id=flow.folder_id,\\n    )\\n\\n    chat_service = get_chat_service()\\n    telemetry_service = get_telemetry_service()\\n    start_time = time.perf_counter()\\n    components_count = None\\n    run_id = str(uuid.uuid4())\\n    try:\\n        with scoped_model_provider_policy_for_flow(\\n            flow,\\n            user_id=current_user.id,\\n            is_superuser=bool(current_user.is_superuser),\\n        ):\\n            if not data:\\n                trusted_data = await _trusted_stored_graph(flow.data, is_superuser=current_user.is_superuser)\\n                if trusted_data is not None:\\n                    graph = await build_and_cache_graph_from_data(\\n                        flow_id=flow_id, graph_data=trusted_data, chat_service=chat_service\\n                    )\\n                else:\\n                    graph = await build_graph_from_db(flow_id=flow_id, session=session, chat_service=chat_service)\\n            else:\\n                sanitized_data = await _trusted_stored_graph(\\n                    data.model_dump(),\\n                    is_superuser=current_user.is_superuser,\\n                )\\n                if sanitized_data is not None:\\n                    data = FlowDataRequest.model_validate(sanitized_data)\\n                graph = await build_and_cache_graph_from_data(\\n                    flow_id=flow_id, graph_data=data.model_dump(), chat_service=chat_service\\n                )\\n            graph = graph.prepare(stop_component_id, start_component_id)\\n        graph.set_run_id(run_id)\\n\\n        # Now vertices is a list of lists\\n        # We need to get the id of each vertex\\n        # and return the same structure but only with the ids\\n        components_count = len(graph.vertices)\\n        vertices_to_run = list(graph.vertices_to_run.union(get_top_level_vertices(graph, graph.vertices_to_run)))\\n        await chat_service.set_cache(str(flow_id), graph)\\n        background_tasks.add_task(\\n            telemetry_service.log_package_playground,\\n            PlaygroundPayload(\\n                playground_seconds=int(time.perf_counter() - start_time),\\n                playground_component_count=components_count,\\n                playground_success=True,\\n                playground_run_id=run_id,\\n            ),\\n        )\\n        return VerticesOrderResponse(ids=graph.first_layer, run_id=graph.run_id, vertices_to_run=vertices_to_run)\\n    except Exception as exc:\\n        background_tasks.add_task(\\n            telemetry_service.log_package_playground,\\n            PlaygroundPayload(\\n                playground_seconds=int(time.perf_counter() - start_time),\\n                playground_component_count=components_count,\\n                playground_success=False,\\n                playground_error_message=str(exc),\\n                playground_run_id=run_id,\\n            ),\\n        )\\n        # A policy refusal already carries its status; re-wrapping it as 500 would report\\n        # an authorization decision as a server fault. Telemetry above still records it.\\n        if isinstance(exc, HTTPException):\\n            raise\\n        if \\\"stream or streaming set to True\\\" in str(exc):\\n            raise HTTPException(status_code=400, detail=str(exc)) from exc\\n        if isinstance(exc, CustomComponentValidationError):\\n            raise HTTPException(status_code=400, detail=str(exc)) from exc\\n        if isinstance(exc, RuntimeError):\\n            raise HTTPException(status_code=503, detail=str(exc)) from exc\\n        await logger.aexception(\\\"Error checking build status\\\")\\n        raise HTTPException(status_code=500, detail=str(exc)) from exc\\n\\n\\n@router.post(\\\"/build/{flow_id}/flow\\\")\\nasync def build_flow(\\n    *,\\n    flow_id: uuid.UUID,\\n    background_tasks: LimitVertexBuildBackgroundTasks,\\n    inputs: Annotated[InputValueRequest | None, Body(embed=True)] = None,\\n    data: Annotated[FlowDataRequest | None, Body(embed=True)] = None,\\n    files: list[str] | None = None,\\n    stop_component_id: str | None = None,\\n    start_component_id: str | None = None,\\n    log_builds: bool = True,\\n    current_user: CurrentActiveUser,\\n    queue_service: Annotated[JobQueueService, Depends(get_queue_service)],\\n    flow_name: str | None = None,\\n    event_delivery: EventDeliveryType = EventDeliveryType.POLLING,\\n):\\n    \\\"\\\"\\\"Build and process a flow, returning a job ID for event polling.\\n\\n    This endpoint requires authentication through the CurrentActiveUser dependency.\\n    For public flows that don't require authentication, use the /build_public_tmp/flow_id/flow endpoint.\\n\\n    Args:\\n        flow_id: UUID of the flow to build\\n        background_tasks: Background tasks manager\\n        inputs: Optional input values for the flow\\n        data: Optional flow data\\n        files: Optional files to include\\n        stop_component_id: Optional ID of component to stop at\\n        start_component_id: Optional ID of component to start from\\n        log_builds: Whether to log the build process\\n        current_user: The authenticated user\\n        queue_service: Queue service for job management\\n        flow_name: Optional name for the flow\\n        event_delivery: Optional event delivery type - default is streaming\\n\\n    Returns:\\n        Dict with job_id that can be used to poll for build status\\n    \\\"\\\"\\\"\\n    # Share-aware load: when the authorization plugin signals cross-user fetch\\n    # support, the row loads by id alone and the plugin decides. Otherwise we\\n    # keep the historical owner-or-PUBLIC scoping so the OSS pass-through\\n    # default cannot widen visibility. PUBLIC flows stay buildable by any\\n    # authenticated user in both modes.\\n    from langflow.api.v1.flows_helpers import _read_flow\\n\\n    async with session_scope() as session:\\n        flow = await _read_flow(session, flow_id, current_user.id)\\n        if flow is None:\\n            public_stmt = select(Flow).where(\\n                Flow.id == flow_id,\\n                Flow.access_type == AccessTypeEnum.PUBLIC,\\n            )\\n            flow = (await session.exec(public_stmt)).first()\\n        if not flow:\\n            await logger.awarning(\\n                \\\"Flow access denied for user %s: flow %s not found or not owned\\\",\\n                current_user.id,\\n                flow_id,\\n            )\\n            raise HTTPException(status_code=404, detail=f\\\"Flow with id {flow_id} not found\\\")\\n\\n    # Authorize the execute action \u2014 runs the authorization plugin if registered,\\n    # no-op in OSS pass-through. Audited regardless. A plugin deny becomes 404\\n    # so a caller who cannot see the flow cannot enumerate UUIDs by probing for\\n    # 403 vs 404. A caller who *can* read it has already seen the flow, so that\\n    # mask buys nothing and only hides which permission they are missing \u2014 the\\n    # Playground is exactly this case.\\n    try:\\n        await ensure_flow_permission(\\n            current_user,\\n            FlowAction.EXECUTE,\\n            flow_id=flow_id,\\n            flow_user_id=flow.user_id,\\n            workspace_id=flow.workspace_id,\\n            folder_id=flow.folder_id,\\n        )\\n    except HTTPException as exc:\\n        raise await deny_to_404_unless_readable(\\n            exc,\\n            lambda: ensure_flow_permission(\\n                current_user,\\n                FlowAction.READ,\\n                flow_id=flow_id,\\n                flow_user_id=flow.user_id,\\n                workspace_id=flow.workspace_id,\\n                folder_id=flow.folder_id,\\n            ),\\n            denied_detail=FLOW_EXECUTE_DENIED_DETAIL,\\n            not_found_detail=f\\\"Flow with id {flow_id} not found\\\",\\n        ) from exc\\n\\n    # Execute-only callers must run the stored graph \u2014 they cannot inject an\\n    # alternate definition and have it run under the owner's resources. This\\n    # drops the override rather than denying: the caller holds ``flow:execute``,\\n    # so the run itself is theirs to make, and denying it reported the flow as\\n    # non-existent to someone already looking at it (LE-1905). Overriding is an\\n    # edit expressed at run time, so it is gated on ``flow:write``.\\n    if data is not None and not await resolve_flow_data_override(current_user, flow):\\n        await logger.ainfo(\\n            \\\"Ignoring caller-supplied flow data for flow %s: caller may execute but not edit it.\\\",\\n            flow_id,\\n        )\\n        data = None\\n\\n    try:\\n        if data:\\n            raw_data = data.model_dump()\\n            sanitized_data = await prepare_flow_build_for_user(\\n                raw_data,\\n                is_superuser=current_user.is_superuser,\\n            )\\n            if sanitized_data is not None:\\n                data = FlowDataRequest.model_validate(sanitized_data)\\n        elif flow and flow.data:\\n            # Stored graphs are caller-controlled too: any user who can write a flow can\\n            # persist component source through the ordinary flow API and then execute it by\\n            # building with an empty body. The global validator does not know the caller, so\\n            # it cannot enforce ``custom_component_admin_only`` here. Run the same caller-aware\\n            # policy the inline branch runs, and build from the detached copy it returns so the\\n            # worker compiles the server's trusted source rather than the stored bytes.\\n            # A permissive policy returns ``None`` and the build still loads from the DB.\\n            sanitized_data = await prepare_flow_build_for_user(\\n                flow.data,\\n                is_superuser=current_user.is_superuser,\\n            )\\n            if sanitized_data is not None:\\n                data = FlowDataRequest(\\n                    nodes=sanitized_data.get(\\\"nodes\\\", []),\\n                    edges=sanitized_data.get(\\\"edges\\\", []),\\n                    viewport=sanitized_data.get(\\\"viewport\\\"),\\n                )\\n    except CatalogPolicyIdentityUnavailableError as exc:\\n        raise HTTPException(status_code=503, detail=str(exc)) from exc\\n    except CustomComponentValidationError as exc:\\n        raise HTTPException(status_code=400, detail=str(exc)) from exc\\n    except RuntimeError as exc:\\n        raise HTTPException(status_code=503, detail=str(exc)) from exc\\n\\n    # v1.build, not \\\"playground\\\": the canvas moved to POST /api/v2/workflows and the frontend\\n    # has no reference to this route left (15 hits for api/v2/workflows, 0 for api/v1/build).\\n    # What still arrives here is direct API callers and voice, so labelling it playground would\\n    # attribute IDE traffic to a route the IDE no longer uses. The playground label is derived\\n    # from the agui wire protocol on the v2 stream instead.\\n    #\\n    # Still a default rather than the truth for every caller: voice reaches this same function\\n    # through build_flow_and_stream and binds its own protocol first, which wins.\\n    with execution_protocol(\\\"v1.build\\\"):\\n        job_id = await start_flow_build(\\n            flow_id=flow_id,\\n            provider_policy_flow=flow,\\n            background_tasks=background_tasks,\\n            inputs=inputs,\\n            data=data,\\n            files=files,\\n            stop_component_id=stop_component_id,\\n            start_component_id=start_component_id,\\n            log_builds=log_builds,\\n            current_user=current_user,\\n            queue_service=queue_service,\\n            flow_name=flow_name,\\n            source_flow_owner_id=flow.user_id,\\n            expose_error_details=flow.user_id == current_user.id,\\n        )\\n    await _register_job_owner_or_cancel(queue_service, job_id, current_user.id)\\n\\n    # This is required to support FE tests - we need to be able to set the event delivery to direct\\n    if event_delivery != EventDeliveryType.DIRECT:\\n        return {\\\"job_id\\\": job_id}\\n    return await get_flow_events_response(\\n        job_id=job_id,\\n        queue_service=queue_service,\\n        event_delivery=event_delivery,\\n    )\\n\\n\\n@router.get(\\\"/build/{job_id}/events\\\")\\nasync def get_build_events(\\n    job_id: str,\\n    queue_service: Annotated[JobQueueService, Depends(get_queue_service)],\\n    current_user: CurrentActiveUser,\\n    *,\\n    event_delivery: EventDeliveryType = EventDeliveryType.STREAMING,\\n):\\n    \\\"\\\"\\\"Get events for a specific build job.\\n\\n    Requires authentication and ownership verification. A job owner is registered\\n    when build_flow is called; if a registered owner does not match the requesting\\n    user the endpoint returns 404 to avoid leaking job existence.\\n    Jobs started via build_public_tmp have no registered owner and remain accessible\\n    to any authenticated user.\\n    \\\"\\\"\\\"\\n    await _verify_job_ownership(job_id, current_user, queue_service)\\n    return await get_flow_events_response(\\n        job_id=job_id,\\n        queue_service=queue_service,\\n        event_delivery=event_delivery,\\n    )\\n\\n\\n@router.post(\\n    \\\"/build/{job_id}/cancel\\\",\\n    response_model=CancelFlowResponse,\\n)\\nasync def cancel_build(\\n    job_id: str,\\n    queue_service: Annotated[JobQueueService, Depends(get_queue_service)],\\n    current_user: CurrentActiveUser,\\n):\\n    \\\"\\\"\\\"Cancel a specific build job.\\n\\n    Requires authentication and ownership verification to prevent a user from\\n    aborting another user's running build (DoS via job cancellation).\\n    Jobs with no registered owner (build_public_tmp) are accessible to any\\n    authenticated user, consistent with get_build_events.\\n    \\\"\\\"\\\"\\n    await _verify_job_ownership(job_id, current_user, queue_service)\\n    try:\\n        # Cancel the flow build and check if it was successful\\n        cancellation_success = await cancel_flow_build(job_id=job_id, queue_service=queue_service)\\n\\n        if cancellation_success:\\n            # Cancellation succeeded or wasn't needed\\n            return CancelFlowResponse(success=True, message=\\\"Flow build cancelled successfully\\\")\\n        # Cancellation was attempted but failed\\n        return CancelFlowResponse(success=False, message=\\\"Failed to cancel flow build\\\")\\n    except asyncio.CancelledError:\\n        # If CancelledError reaches here, it means the task was not successfully cancelled\\n        await logger.aerror(f\\\"Failed to cancel flow build for job_id {job_id} (CancelledError caught)\\\")\\n        return CancelFlowResponse(success=False, message=\\\"Failed to cancel flow build\\\")\\n    except ValueError as exc:\\n        # Job not found\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=str(exc)) from exc\\n    except JobQueueNotFoundError as exc:\\n        await logger.aerror(f\\\"Job not found: {job_id}. Error: {exc!s}\\\")\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=f\\\"Job not found: {exc!s}\\\") from exc\\n    except Exception as exc:\\n        # Any other unexpected error\\n        await logger.aexception(f\\\"Error cancelling flow build for job_id {job_id}: {exc}\\\")\\n        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=str(exc)) from exc\\n\\n\\n@router.post(\\\"/build/{flow_id}/vertices/{vertex_id}\\\", deprecated=True, include_in_schema=False)\\nasync def build_vertex(\\n    *,\\n    flow_id: uuid.UUID,\\n    vertex_id: str,\\n    background_tasks: BackgroundTasks,\\n    inputs: Annotated[InputValueRequest | None, Body(embed=True)] = None,\\n    files: list[str] | None = None,\\n    current_user: CurrentActiveUser,\\n) -> VertexBuildResponse:\\n    \\\"\\\"\\\"Build a vertex instead of the entire graph.\\n\\n    Args:\\n        flow_id (str): The ID of the flow.\\n        vertex_id (str): The ID of the vertex to build.\\n        background_tasks (BackgroundTasks): The background tasks dependency.\\n        inputs (Optional[InputValueRequest], optional): The input values for the vertex. Defaults to None.\\n        files (List[str], optional): The files to use. Defaults to None.\\n        current_user (Any, optional): The current user dependency. Defaults to Depends(get_current_active_user).\\n\\n    Returns:\\n        VertexBuildResponse: The response containing the built vertex information.\\n\\n    Raises:\\n        HTTPException: If there is an error building the vertex.\\n\\n    \\\"\\\"\\\"\\n    # This deprecated editor route is owner-only because its graph cache is\\n    # keyed by flow UUID rather than execution principal.\\n    async with session_scope() as authz_session:\\n        stmt = select(Flow).where(Flow.id == flow_id).where(Flow.user_id == current_user.id)\\n        flow = (await authz_session.exec(stmt)).first()\\n    if not flow:\\n        raise HTTPException(status_code=404, detail=f\\\"Flow with id {flow_id} not found\\\")\\n    await ensure_flow_permission(\\n        current_user,\\n        FlowAction.EXECUTE,\\n        flow_id=flow_id,\\n        flow_user_id=flow.user_id,\\n        workspace_id=flow.workspace_id,\\n        folder_id=flow.folder_id,\\n    )\\n\\n    sanitized_data = await _trusted_stored_graph(flow.data, is_superuser=current_user.is_superuser)\\n\\n    chat_service = get_chat_service()\\n    telemetry_service = get_telemetry_service()\\n    flow_id_str = str(flow_id)\\n\\n    next_runnable_vertices = []\\n    top_level_vertices = []\\n    start_time = time.perf_counter()\\n    error_message = None\\n    run_id = None\\n    try:\\n        graph: Graph = await chat_service.get_cache(flow_id_str)\\n    except KeyError as exc:\\n        raise HTTPException(status_code=404, detail=\\\"Graph not found\\\") from exc\\n\\n    try:\\n        cache = await chat_service.get_cache(flow_id_str)\\n        cached_graph = None if isinstance(cache, CacheMiss) else cache.get(\\\"result\\\")\\n        # This seam is incremental: it is called once per vertex and carries built state in\\n        # the cache between calls. The policy hands back a copy on EVERY request from a\\n        # non-superuser, so rebuilding on that alone discarded the previous vertex's result\\n        # and the next one reported its upstream as unbuilt. Rebuild only when the cached\\n        # compilation did not come from this copy \u2014 which still covers the case the rebuild\\n        # exists for, a graph compiled while the policy was off.\\n        needs_initialize_run = True\\n        if sanitized_data is not None and not _compiled_from(cached_graph, sanitized_data):\\n            # Graph CONSTRUCTION binds the provider scope too, not just execution.\\n            with scoped_model_provider_policy_for_flow(\\n                flow,\\n                user_id=current_user.id,\\n                is_superuser=bool(current_user.is_superuser),\\n            ):\\n                graph = await build_and_cache_graph_from_data(\\n                    flow_id=flow_id_str,\\n                    chat_service=chat_service,\\n                    graph_data=sanitized_data,\\n                )\\n            run_id = str(uuid.uuid4())\\n            graph.set_run_id(run_id)\\n        elif cached_graph is None:\\n            # If there's no cache\\n            await logger.awarning(f\\\"No cache found for {flow_id_str}. Building graph starting at {vertex_id}\\\")\\n            with scoped_model_provider_policy_for_flow(\\n                flow,\\n                user_id=current_user.id,\\n                is_superuser=bool(current_user.is_superuser),\\n            ):\\n                async with session_scope() as session:\\n                    graph = await build_graph_from_db(\\n                        flow_id=flow_id,\\n                        session=session,\\n                        chat_service=chat_service,\\n                    )\\n            run_id = str(uuid.uuid4())\\n            graph.set_run_id(run_id)\\n            # build_graph_from_db initializes the run itself.\\n            needs_initialize_run = False\\n        else:\\n            graph = cached_graph\\n        try:\\n            _validate_graph_for_execution(graph)\\n        except HTTPException:\\n            await _clear_invalid_graph_cache(chat_service, flow_id_str)\\n            raise\\n        if needs_initialize_run:\\n            with scoped_model_provider_policy_for_flow(\\n                flow,\\n                user_id=current_user.id,\\n                is_superuser=bool(current_user.is_superuser),\\n            ):\\n                await graph.initialize_run()\\n            run_id = graph.run_id\\n        vertex = graph.get_vertex(vertex_id)\\n\\n        try:\\n            lock = chat_service.async_cache_locks[flow_id_str]\\n            with scoped_model_provider_policy_for_flow(\\n                flow,\\n                user_id=current_user.id,\\n                is_superuser=bool(current_user.is_superuser),\\n            ):\\n                vertex_build_result = await graph.build_vertex(\\n                    vertex_id=vertex_id,\\n                    user_id=str(current_user.id),\\n                    inputs_dict=inputs.model_dump() if inputs else {},\\n                    files=files,\\n                    get_cache=chat_service.get_cache,\\n                    set_cache=chat_service.set_cache,\\n                )\\n            result_dict = vertex_build_result.result_dict\\n            params = vertex_build_result.params\\n            valid = vertex_build_result.valid\\n            artifacts = vertex_build_result.artifacts\\n            next_runnable_vertices = await graph.get_next_runnable_vertices(lock, vertex=vertex, cache=False)\\n            top_level_vertices = graph.get_top_level_vertices(next_runnable_vertices)\\n            result_data_response = ResultDataResponse.model_validate(result_dict, from_attributes=True)\\n        except Exception as exc:  # noqa: BLE001\\n            if isinstance(exc, ComponentBuildError):\\n                params = exc.message\\n                tb = exc.formatted_traceback\\n            else:\\n                tb = traceback.format_exc()\\n                await logger.aexception(\\\"Error building Component\\\")\\n                params = format_exception_message(exc)\\n            message = {\\\"errorMessage\\\": params, \\\"stackTrace\\\": tb}\\n            valid = False\\n            error_message = params\\n            output_label = vertex.outputs[0][\\\"name\\\"] if vertex.outputs else \\\"output\\\"\\n            outputs = {output_label: OutputValue(message=message, type=\\\"error\\\")}\\n            result_data_response = ResultDataResponse(results={}, outputs=outputs)\\n            artifacts = {}\\n            background_tasks.add_task(graph.end_all_traces_in_context(error=exc))\\n            # If there's an error building the vertex\\n            # we need to clear the cache\\n            await chat_service.clear_cache(flow_id_str)\\n\\n        result_data_response.message = artifacts\\n\\n        # Log the vertex build\\n        if not vertex.will_stream:\\n            background_tasks.add_task(\\n                log_vertex_build,\\n                flow_id=flow_id_str,\\n                vertex_id=vertex_id,\\n                valid=valid,\\n                params=params,\\n                data=result_data_response,\\n                artifacts=artifacts,\\n            )\\n\\n        timedelta = time.perf_counter() - start_time\\n\\n        duration = format_elapsed_time(timedelta)\\n        result_data_response.duration = duration\\n        result_data_response.timedelta = timedelta\\n        vertex.add_build_time(timedelta)\\n        inactivated_vertices = list(graph.inactivated_vertices)\\n        graph.reset_inactivated_vertices(vertex.id)\\n        graph.reset_activated_vertices()\\n\\n        await chat_service.set_cache(flow_id_str, graph)\\n\\n        # graph.stop_vertex tells us if the user asked\\n        # to stop the build of the graph at a certain vertex\\n        # if it is in next_vertices_ids, we need to remove other\\n        # vertices from next_vertices_ids\\n        if graph.stop_vertex and graph.stop_vertex in next_runnable_vertices:\\n            next_runnable_vertices = [graph.stop_vertex]\\n\\n        if not graph.run_manager.vertices_being_run and not next_runnable_vertices:\\n            background_tasks.add_task(graph.end_all_traces_in_context())\\n\\n        build_response = VertexBuildResponse(\\n            inactivated_vertices=list(set(inactivated_vertices)),\\n            next_vertices_ids=list(set(next_runnable_vertices)),\\n            top_level_vertices=list(set(top_level_vertices)),\\n            valid=valid,\\n            params=params,\\n            id=vertex.id,\\n            data=result_data_response,\\n        )\\n        background_tasks.add_task(\\n            telemetry_service.log_package_component,\\n            ComponentPayload(\\n                component_name=vertex_id.split(\\\"-\\\")[0],\\n                component_id=vertex_id,\\n                component_seconds=int(time.perf_counter() - start_time),\\n                component_success=valid,\\n                component_error_message=error_message,\\n                component_run_id=run_id,\\n            ),\\n        )\\n    except HTTPException:\\n        raise\\n    except Exception as exc:\\n        background_tasks.add_task(\\n            telemetry_service.log_package_component,\\n            ComponentPayload(\\n                component_name=vertex_id.split(\\\"-\\\")[0],\\n                component_id=vertex_id,\\n                component_seconds=int(time.perf_counter() - start_time),\\n                component_success=False,\\n                component_error_message=str(exc),\\n                component_run_id=run_id if \\\"run_id\\\" in locals() else None,\\n            ),\\n        )\\n        if isinstance(exc, CustomComponentValidationError):\\n            raise HTTPException(status_code=400, detail=str(exc)) from exc\\n        await logger.aexception(\\\"Error building Component\\\")\\n        message = parse_exception(exc)\\n        raise HTTPException(status_code=500, detail=message) from exc\\n\\n    return build_response\\n\\n\\nasync def _stream_vertex(flow_id: str, vertex_id: str, chat_service: ChatService, graph: Graph | None = None):\\n    try:\\n        if graph is None:\\n            try:\\n                cache = await chat_service.get_cache(flow_id)\\n            except Exception as exc:  # noqa: BLE001\\n                await logger.aexception(\\\"Error building Component\\\")\\n                yield str(StreamData(event=\\\"error\\\", data={\\\"error\\\": str(exc)}))\\n                return\\n\\n            if isinstance(cache, CacheMiss):\\n                # If there's no cache\\n                msg = f\\\"No cache found for {flow_id}.\\\"\\n                await logger.aerror(msg)\\n                yield str(StreamData(event=\\\"error\\\", data={\\\"error\\\": msg}))\\n                return\\n            graph = cache.get(\\\"result\\\")\\n\\n        try:\\n            _validate_graph_for_execution(graph)\\n        except HTTPException as exc:\\n            await _clear_invalid_graph_cache(chat_service, flow_id)\\n            graph = None\\n            yield str(StreamData(event=\\\"error\\\", data={\\\"error\\\": exc.detail}))\\n            return\\n\\n        try:\\n            vertex: InterfaceVertex = graph.get_vertex(vertex_id)\\n        except Exception as exc:  # noqa: BLE001\\n            await logger.aexception(\\\"Error building Component\\\")\\n            yield str(StreamData(event=\\\"error\\\", data={\\\"error\\\": str(exc)}))\\n            return\\n\\n        if not hasattr(vertex, \\\"stream\\\"):\\n            msg = f\\\"Vertex {vertex_id} does not support streaming\\\"\\n            await logger.aerror(msg)\\n            yield str(StreamData(event=\\\"error\\\", data={\\\"error\\\": msg}))\\n            return\\n\\n        if isinstance(vertex.built_result, str) and vertex.built_result:\\n            stream_data = StreamData(\\n                event=\\\"message\\\",\\n                data={\\\"message\\\": f\\\"Streaming vertex {vertex_id}\\\"},\\n            )\\n            yield str(stream_data)\\n            stream_data = StreamData(\\n                event=\\\"message\\\",\\n                data={\\\"chunk\\\": vertex.built_result},\\n            )\\n            yield str(stream_data)\\n\\n        elif not vertex.frozen or not vertex.built:\\n            await logger.adebug(f\\\"Streaming vertex {vertex_id}\\\")\\n            stream_data = StreamData(\\n                event=\\\"message\\\",\\n                data={\\\"message\\\": f\\\"Streaming vertex {vertex_id}\\\"},\\n            )\\n            yield str(stream_data)\\n            try:\\n                async for chunk in vertex.stream():\\n                    stream_data = StreamData(\\n                        event=\\\"message\\\",\\n                        data={\\\"chunk\\\": chunk},\\n                    )\\n                    yield str(stream_data)\\n            except Exception as exc:  # noqa: BLE001\\n                await logger.aexception(\\\"Error building Component\\\")\\n                exc_message = parse_exception(exc)\\n                if exc_message == \\\"The message must be an iterator or an async iterator.\\\":\\n                    exc_message = \\\"This stream has already been closed.\\\"\\n                yield str(StreamData(event=\\\"error\\\", data={\\\"error\\\": exc_message}))\\n        elif vertex.result is not None:\\n            stream_data = StreamData(\\n                event=\\\"message\\\",\\n                data={\\\"chunk\\\": vertex.built_result},\\n            )\\n            yield str(stream_data)\\n        else:\\n            msg = f\\\"No result found for vertex {vertex_id}\\\"\\n            await logger.aerror(msg)\\n            yield str(StreamData(event=\\\"error\\\", data={\\\"error\\\": msg}))\\n            return\\n    finally:\\n        await logger.adebug(\\\"Closing stream\\\")\\n        if graph:\\n            await chat_service.set_cache(flow_id, graph)\\n        yield str(StreamData(event=\\\"close\\\", data={\\\"message\\\": \\\"Stream closed\\\"}))\\n\\n\\nasync def _stream_vertex_with_provider_scope(\\n    flow_id: str,\\n    vertex_id: str,\\n    chat_service: ChatService,\\n    graph: Graph | None,\\n    flow: Flow,\\n    current_user: User,\\n):\\n    \\\"\\\"\\\"Retain the trusted flow scope while the response generator is consumed.\\\"\\\"\\\"\\n    with scoped_model_provider_policy_for_flow(\\n        flow,\\n        user_id=current_user.id,\\n        is_superuser=bool(current_user.is_superuser),\\n    ):\\n        async for event in _stream_vertex(flow_id, vertex_id, chat_service, graph):\\n            yield event\\n\\n\\n@router.get(\\n    \\\"/build/{flow_id}/{vertex_id}/stream\\\",\\n    response_class=StreamingResponse,\\n    deprecated=True,\\n    include_in_schema=False,\\n)\\nasync def build_vertex_stream(\\n    flow_id: uuid.UUID,\\n    vertex_id: str,\\n    current_user: CurrentActiveUser,\\n):\\n    \\\"\\\"\\\"Build a vertex instead of the entire graph.\\n\\n    This function is responsible for building a single vertex instead of the entire graph.\\n    It takes the `flow_id` and `vertex_id` as required parameters, and an optional `session_id`.\\n    It also depends on the `ChatService` and `SessionService` services.\\n\\n    If `session_id` is not provided, it retrieves the graph from the cache using the `chat_service`.\\n    If `session_id` is provided, it loads the session data using the `session_service`.\\n\\n    Once the graph is obtained, it retrieves the specified vertex using the `vertex_id`.\\n    If the vertex does not support streaming, an error is raised.\\n    If the vertex has a built result, it sends the result as a chunk.\\n    If the vertex is not frozen or not built, it streams the vertex data.\\n    If the vertex has a result, it sends the result as a chunk.\\n    If none of the above conditions are met, an error is raised.\\n\\n    If any exception occurs during the process, an error message is sent.\\n    Finally, the stream is closed.\\n\\n    Returns:\\n        A `StreamingResponse` object with the streamed vertex data in text/event-stream format.\\n\\n    Raises:\\n        HTTPException: If an error occurs while building the vertex.\\n    \\\"\\\"\\\"\\n    # This deprecated editor route is owner-only. Authorize before constructing\\n    # the streaming response because the cache is keyed only by flow UUID.\\n    async with session_scope() as session:\\n        stmt = select(Flow).where(Flow.id == flow_id).where(Flow.user_id == current_user.id)\\n        flow = (await session.exec(stmt)).first()\\n    if not flow:\\n        raise HTTPException(status_code=404, detail=f\\\"Flow with id {flow_id} not found\\\")\\n    await ensure_flow_permission(\\n        current_user,\\n        FlowAction.EXECUTE,\\n        flow_id=flow_id,\\n        flow_user_id=flow.user_id,\\n        workspace_id=flow.workspace_id,\\n        folder_id=flow.folder_id,\\n    )\\n\\n    chat_service = get_chat_service()\\n    try:\\n        cache = await chat_service.get_cache(str(flow_id))\\n        if isinstance(cache, CacheMiss):\\n            graph = None\\n        else:\\n            graph = cache.get(\\\"result\\\")\\n            try:\\n                _validate_graph_for_execution(graph)\\n            except HTTPException:\\n                await _clear_invalid_graph_cache(chat_service, str(flow_id))\\n                raise\\n        return StreamingResponse(\\n            _stream_vertex_with_provider_scope(\\n                str(flow_id),\\n                vertex_id,\\n                chat_service,\\n                graph,\\n                flow,\\n                current_user,\\n            ),\\n            media_type=\\\"text/event-stream\\\",\\n        )\\n    except HTTPException:\\n        raise\\n    except Exception as exc:\\n        raise HTTPException(status_code=500, detail=\\\"Error building Component\\\") from exc\\n\\n\\nasync def build_flow_and_stream(flow_id, inputs, background_tasks, current_user):\\n    queue_service = get_queue_service()\\n    build_response = await build_flow(\\n        flow_id=flow_id,\\n        inputs=inputs,\\n        background_tasks=background_tasks,\\n        current_user=current_user,\\n        queue_service=queue_service,\\n        event_delivery=EventDeliveryType.STREAMING,\\n    )\\n    job_id = build_response[\\\"job_id\\\"]\\n    return await get_flow_events_response(\\n        job_id=job_id,\\n        queue_service=queue_service,\\n        event_delivery=EventDeliveryType.STREAMING,\\n    )\\n\\n\\n# NOTE: ``validate_public_files`` (the canonical helper that mitigates\\n# GHSA-rcjh-r59h-gq37) was moved to ``langflow.api.utils.flow_utils`` so v2's\\n# public workflow endpoint shares the exact same gate. Keep it imported above.\\n\\n\\n@router.post(\\\"/build_public_tmp/{flow_id}/flow\\\")\\nasync def build_public_tmp(\\n    *,\\n    background_tasks: LimitVertexBuildBackgroundTasks,\\n    flow_id: uuid.UUID,\\n    inputs: Annotated[InputValueRequest | None, Body(embed=True)] = None,\\n    files: list[str] | None = None,\\n    stop_component_id: str | None = None,\\n    start_component_id: str | None = None,\\n    log_builds: bool | None = True,\\n    flow_name: str | None = None,\\n    request: Request,\\n    queue_service: Annotated[JobQueueService, Depends(get_queue_service)],\\n    authenticated_user: Annotated[User | None, Depends(get_current_user_optional)] = None,\\n    event_delivery: EventDeliveryType = EventDeliveryType.POLLING,\\n):\\n    \\\"\\\"\\\"Build a public flow without requiring authentication.\\n\\n    This endpoint is specifically for public flows that don't require authentication.\\n    It uses a client_id cookie to create a deterministic flow ID for tracking purposes.\\n\\n    Security Note:\\n    - The 'data' parameter is NOT accepted to prevent flow definition tampering\\n    - Public flows must execute the stored flow definition only\\n    - The flow definition is always loaded from the database\\n    - Caller-supplied 'inputs.session' is namespaced under the (client_id,\\n      flow_id) virtual flow ID so an unauthenticated caller cannot address a\\n      session that lives outside its own namespace (CVE-2026-33017)\\n\\n    The endpoint:\\n    1. Verifies the requested flow is marked as public in the database\\n    2. Creates a deterministic UUID based on client_id and flow_id\\n    3. Uses a stable anonymous principal to build the flow\\n    4. Always loads the flow definition from the database\\n\\n    Requirements:\\n    - The flow must be marked as PUBLIC in the database\\n    - The request must include a client_id cookie\\n\\n    Args:\\n        flow_id: UUID of the public flow to build\\n        background_tasks: Background tasks manager\\n        inputs: Optional input values for the flow\\n        files: Optional files to include\\n        stop_component_id: Optional ID of component to stop at\\n        start_component_id: Optional ID of component to start from\\n        log_builds: Whether to log the build process\\n        flow_name: Optional name for the flow\\n        request: FastAPI request object (needed for cookie access)\\n        queue_service: Queue service for job management\\n        authenticated_user: Optional authenticated user (resolved from cookie/token if present)\\n        event_delivery: Optional event delivery type - default is streaming\\n\\n    Returns:\\n        Dict with job_id that can be used to poll for build status\\n    \\\"\\\"\\\"\\n    settings = get_settings_service().settings\\n    if settings.rate_limit_enabled:\\n        check_rate_limit(\\n            request,\\n            scope=f\\\"public-build:{flow_id}\\\",\\n            limit_per_minute=settings.public_flow_rate_limit_per_minute,\\n        )\\n\\n    try:\\n        # Reject caller-supplied file references that aren't scoped to this\\n        # public flow's own storage namespace. Done before any flow lookup so\\n        # malformed requests fail fast and don't touch the DB.\\n        validate_public_files(files, flow_id)\\n\\n        # Verify the direct-link grant and derive the anonymous runtime principal.\\n        client_id = request.cookies.get(\\\"client_id\\\")\\n        # Only use authenticated user_id when auto-login is disabled.\\n        # When AUTO_LOGIN=TRUE, the frontend uses client_id for UUID v5,\\n        # so the backend must match to avoid flow_id mismatch.\\n        auth_settings = get_settings_service().auth_settings\\n        authenticated_user_id = authenticated_user.id if authenticated_user and not auth_settings.AUTO_LOGIN else None\\n        public_user, new_flow_id = await verify_public_flow_and_get_user(\\n            flow_id=flow_id,\\n            client_id=client_id,\\n            authenticated_user_id=authenticated_user_id,\\n            request_host=request.url.hostname,\\n        )\\n\\n        # Defends CVE-2026-33017: scope caller session into the (client_id, flow_id) namespace.\\n        if inputs is not None and inputs.session is not None:\\n            scoped_session = scope_session_to_namespace(inputs.session, str(new_flow_id))\\n            if scoped_session != inputs.session:\\n                inputs = inputs.model_copy(update={\\\"session\\\": scoped_session})\\n\\n        # Validate the stored flow data after the public-access boundary. Public flows never\\n        # accept client-supplied data; the two checks below harden the unauthenticated build\\n        # path (report H1-3754930) and only ever run server-trusted code for anonymous visitors.\\n        sanitized_public_data: dict | None = None\\n        async with session_scope() as session:\\n            flow = await session.get(Flow, flow_id)\\n            if flow is None:\\n                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=PUBLIC_FLOW_NOT_FOUND_DETAIL)\\n            # The admission helper authorizes its own DB snapshot. Reauthorize the\\n            # exact snapshot detached below so a concurrent revoke/private transition\\n            # cannot leave us executing a later, unchecked definition.\\n            await authorize_public_flow_access(\\n                flow=flow,\\n                action=PublicResourceAction.EXECUTE,\\n                request_host=request.url.hostname,\\n                session=session,\\n            )\\n            if flow.data is None:\\n                msg = \\\"Public flow has no executable data\\\"\\n                raise ValueError(msg)\\n\\n            # The default anonymous build path sanitizes component code directly\\n            # and therefore does not call validate_flow_for_current_settings.\\n            # Enforce the exact catalog snapshot after the public-access check\\n            # and before any graph is queued or built. The explicit public-custom\\n            # opt-in already runs the unified validator inside prepare_public_flow_build.\\n            if not settings.allow_public_custom_components:\\n                validate_catalog_policy_for_flow(flow.data)\\n            # Block unauthenticated builds of flows that run arbitrary code\\n            # (Python interpreter/REPL, legacy Python Code Structured tool,\\n            # Smart Transform lambda) or invoke another saved flow (Run Flow,\\n            # Sub Flow, Flow as Tool \u2014 the transitive case). Without this, any\\n            # public flow containing such a component is an unauthenticated\\n            # server-side code-execution primitive (report H1-3754930).\\n            validate_public_flow_no_code_execution(flow.data)\\n            # Substitute the server's trusted code into every known component and\\n            # reject unrecognized custom components, so anonymous visitors only ever\\n            # run server code. The explicit allow_public_custom_components opt-in\\n            # preserves approved stored code, but the detached graph is still\\n            # secret-scrubbed below before it reaches the executor.\\n            prepared_public_data = await prepare_public_flow_build(flow.data)\\n            sanitized_public_data = strip_secret_field_values(\\n                prepared_public_data if prepared_public_data is not None else flow.data\\n            )\\n\\n        # flow_id=new_flow_id for tracking/sessions/messages (virtual, per-user isolation).\\n        # source_flow_id=flow_id to load the actual flow data from the database.\\n        # Anonymous shared-link traffic on the v1 build route. Named for the route rather than\\n        # the surface, for the same reason as v1.build above; the v2 public stream is v2.public.\\n        with execution_protocol(\\\"v1.build.public\\\"):\\n            job_id = await start_flow_build(\\n                flow_id=new_flow_id,\\n                source_flow_id=flow_id,\\n                provider_policy_flow=flow,\\n                background_tasks=background_tasks,\\n                inputs=inputs,\\n                # Build from a detached server-sanitized graph. The default path also\\n                # substitutes trusted code; the explicit custom-component opt-in keeps\\n                # approved code but still strips every persisted secret-bearing field.\\n                data=(\\n                    FlowDataRequest(\\n                        nodes=sanitized_public_data.get(\\\"nodes\\\", []),\\n                        edges=sanitized_public_data.get(\\\"edges\\\", []),\\n                        viewport=sanitized_public_data.get(\\\"viewport\\\"),\\n                    )\\n                    if sanitized_public_data is not None\\n                    else None\\n                ),\\n                files=files,\\n                stop_component_id=stop_component_id,\\n                start_component_id=start_component_id,\\n                log_builds=log_builds or False,\\n                current_user=public_user,\\n                queue_service=queue_service,\\n                flow_name=flow_name or f\\\"{authenticated_user_id or client_id}_{flow_id}\\\",\\n                source_flow_owner_id=flow.user_id,\\n                expose_error_details=False,\\n            )\\n        # Gate the public events/cancel endpoints to jobs that were actually\\n        # started through this public build path, preventing unauthenticated\\n        # callers from reading or cancelling private-flow builds by job_id.\\n        await queue_service.register_public_job(job_id)\\n    except TweakRefusedError:\\n        # Let the app-level handler return the documented structured 422.\\n        raise\\n    except CatalogPolicyIdentityUnavailableError as exc:\\n        await logger.awarning(\\\"Public flow component identities are temporarily unavailable\\\")\\n        raise HTTPException(status_code=503, detail=PUBLIC_CATALOG_POLICY_UNAVAILABLE_MESSAGE) from exc\\n    except CustomComponentValidationError as exc:\\n        await logger.awarning(f\\\"Public flow validation failed: {exc}\\\")\\n        raise HTTPException(status_code=400, detail=\\\"This flow cannot be executed.\\\") from exc\\n    except JobQueueBackendUnavailableError as exc:\\n        # The public marker could not be persisted to the shared (Redis) backend.\\n        # Returning the job_id anyway would hand back an un-shareable id: on a\\n        # multi-worker deployment every other worker's public events/cancel\\n        # endpoints would 404 it. Cancel the just-started build (best-effort) and\\n        # surface a clean 503 instead of a 500 / an unusable job_id.\\n        try:\\n            await queue_service.cancel_job(job_id)\\n        except Exception as cancel_exc:  # noqa: BLE001\\n            await logger.awarning(\\n                f\\\"Failed to cancel public job {job_id} after marker persistence failed: {cancel_exc!r}\\\"\\n            )\\n        raise HTTPException(status_code=503, detail=\\\"Public flow service is temporarily unavailable.\\\") from exc\\n    except ValueError as exc:\\n        await logger.awarning(f\\\"Public flow validation failed: {exc}\\\")\\n        raise HTTPException(status_code=400, detail=\\\"This flow cannot be executed.\\\") from exc\\n    except Exception as exc:\\n        await logger.aexception(\\\"Error building public flow\\\")\\n        if isinstance(exc, HTTPException):\\n            raise\\n        raise HTTPException(status_code=500, detail=\\\"Flow execution failed.\\\") from exc\\n    if event_delivery != EventDeliveryType.DIRECT:\\n        return {\\\"job_id\\\": job_id}\\n    return await get_flow_events_response(\\n        job_id=job_id,\\n        queue_service=queue_service,\\n        event_delivery=event_delivery,\\n    )\\n\\n\\nasync def _assert_public_job(job_id: str, queue_service: JobQueueService) -> None:\\n    \\\"\\\"\\\"Raise HTTP 404 if job_id was not registered through the public build endpoint.\\n\\n    Prevents unauthenticated callers from reading or cancelling private-flow\\n    builds by guessing or leaking a job_id.\\n\\n    Why 404 not 403: returning 403 would confirm the job exists under a different\\n    access tier, leaking information about private builds. 404 is neutral.\\n    \\\"\\\"\\\"\\n    if not await queue_service.is_public_job_async(job_id):\\n        # Static detail \u2014 do not reflect job_id back; avoid confirming which IDs exist.\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Job not found\\\")\\n\\n\\n_PUBLIC_JOB_NOT_FOUND_DETAIL = \\\"Job not found\\\"\\n_PUBLIC_EVENTS_UNAVAILABLE_DETAIL = \\\"Public flow events are unavailable.\\\"\\n_PUBLIC_CANCEL_FAILED_DETAIL = \\\"Public flow cancellation failed.\\\"\\n\\n\\n@router.get(\\\"/build_public_tmp/{job_id}/events\\\")\\nasync def get_build_events_public(\\n    job_id: str,\\n    queue_service: Annotated[JobQueueService, Depends(get_queue_service)],\\n    *,\\n    event_delivery: EventDeliveryType = EventDeliveryType.STREAMING,\\n):\\n    \\\"\\\"\\\"Get events for a public flow build job.\\n\\n    This endpoint does not require authentication, matching the public build endpoint.\\n    It is used by the shareable playground to consume build events.\\n    \\\"\\\"\\\"\\n    await _assert_public_job(job_id, queue_service)\\n    try:\\n        return await get_flow_events_response(\\n            job_id=job_id,\\n            queue_service=queue_service,\\n            event_delivery=event_delivery,\\n        )\\n    except HTTPException as exc:\\n        # The shared authenticated helper carries backend exception text in\\n        # ``detail``. Preserve it in server logs, but public callers get only a\\n        # fixed response. A 404 stays indistinguishable from the registry gate.\\n        await logger.aerror(\\n            f\\\"Public flow events failed for job_id {job_id}: status={exc.status_code} detail={exc.detail!r}\\\"\\n        )\\n        detail = (\\n            _PUBLIC_JOB_NOT_FOUND_DETAIL\\n            if exc.status_code == status.HTTP_404_NOT_FOUND\\n            else _PUBLIC_EVENTS_UNAVAILABLE_DETAIL\\n        )\\n        raise HTTPException(status_code=exc.status_code, detail=detail) from exc\\n    except Exception as exc:\\n        await logger.aexception(f\\\"Public flow events failed for job_id {job_id}: {exc!r}\\\")\\n        raise HTTPException(\\n            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n            detail=_PUBLIC_EVENTS_UNAVAILABLE_DETAIL,\\n        ) from exc\\n\\n\\n@router.post(\\n    \\\"/build_public_tmp/{job_id}/cancel\\\",\\n    response_model=CancelFlowResponse,\\n)\\nasync def cancel_build_public(\\n    job_id: str,\\n    queue_service: Annotated[JobQueueService, Depends(get_queue_service)],\\n):\\n    \\\"\\\"\\\"Cancel a public flow build job.\\n\\n    This endpoint does not require authentication, matching the public build endpoint.\\n    It is used by the shareable playground to cancel builds.\\n    \\\"\\\"\\\"\\n    await _assert_public_job(job_id, queue_service)\\n    try:\\n        cancellation_success = await cancel_flow_build(job_id=job_id, queue_service=queue_service)\\n\\n        if cancellation_success:\\n            return CancelFlowResponse(success=True, message=\\\"Flow build cancelled successfully\\\")\\n        return CancelFlowResponse(success=False, message=\\\"Failed to cancel flow build\\\")\\n    except asyncio.CancelledError as exc:\\n        await logger.aerror(f\\\"Failed to cancel public flow build for job_id {job_id}: {exc!r}\\\")\\n        raise\\n    except ValueError as exc:\\n        await logger.awarning(f\\\"Public flow cancellation could not find job_id {job_id}: {exc!r}\\\")\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=_PUBLIC_JOB_NOT_FOUND_DETAIL) from exc\\n    except JobQueueNotFoundError as exc:\\n        await logger.aerror(f\\\"Public job not found: {job_id}. Error: {exc!s}\\\")\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=_PUBLIC_JOB_NOT_FOUND_DETAIL) from exc\\n    except Exception as exc:\\n        await logger.aexception(f\\\"Error cancelling public flow build for job_id {job_id}: {exc!r}\\\")\\n        raise HTTPException(\\n            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n            detail=_PUBLIC_CANCEL_FAILED_DETAIL,\\n        ) from exc\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/custom_component_policy.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"953f19f5ef5e39cec73ed98de7f529161a567335312d3d543cf4d280a1a83d08\",\"content\":\"\\\"\\\"\\\"Shared catalog and custom-code policy for component source entry points.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom fastapi import HTTPException, status\\nfrom lfx.interface.components import component_cache\\nfrom lfx.utils.flow_validation import (\\n    CatalogPolicyIdentityUnavailableError,\\n    CatalogPolicyValidationError,\\n    code_hash_matches_any_template,\\n    get_component_hash_lookups_for_validation,\\n    get_trusted_code_for_validation,\\n    validate_catalog_policy_for_component_code,\\n    validate_catalog_policy_for_component_type,\\n)\\n\\nif TYPE_CHECKING:\\n    from lfx.services.catalog_policy.base import CatalogPolicySnapshot\\n\\n    from langflow.services.database.models.user.model import User\\n\\n\\n_TEMPLATES_INITIALIZING_MESSAGE = \\\"Component templates are still initializing. Please try again in a few seconds.\\\"\\n\\n\\nclass CatalogPolicyHTTPException(HTTPException):\\n    \\\"\\\"\\\"HTTP denial raised specifically by custom-component catalog policy.\\\"\\\"\\\"\\n\\n\\ndef resolve_component_code_for_action(\\n    code: str,\\n    *,\\n    user: User,\\n    settings: object,\\n    snapshot: CatalogPolicySnapshot,\\n    disabled_detail: str,\\n    admin_only_detail: str,\\n) -> str:\\n    \\\"\\\"\\\"Return executable/validated source after applying catalog and custom-code policy.\\n\\n    Catalog denial is evaluated first and has no superuser bypass. Restricted\\n    custom-code modes continue to permit known server templates, but callers\\n    receive the trusted server copy instead of executing client-submitted bytes.\\n    \\\"\\\"\\\"\\n    try:\\n        validate_catalog_policy_for_component_code(code, snapshot=snapshot)\\n    except CatalogPolicyValidationError as exc:\\n        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=str(exc)) from exc\\n    except CatalogPolicyIdentityUnavailableError as exc:\\n        raise HTTPException(status_code=status.HTTP_503_SERVICE_UNAVAILABLE, detail=str(exc)) from exc\\n\\n    admin_only = getattr(settings, \\\"custom_component_admin_only\\\", False) is True and not user.is_superuser\\n    custom_code_disabled = not getattr(settings, \\\"allow_custom_components\\\", True)\\n    if not custom_code_disabled and not admin_only:\\n        return code\\n\\n    get_component_hash_lookups_for_validation()\\n    all_known = component_cache.all_known_hashes\\n    if all_known is None:\\n        raise HTTPException(\\n            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n            detail=_TEMPLATES_INITIALIZING_MESSAGE,\\n        )\\n\\n    if not code_hash_matches_any_template(code, all_known):\\n        detail = disabled_detail if custom_code_disabled else admin_only_detail\\n        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=detail)\\n\\n    trusted_code = get_trusted_code_for_validation(code)\\n    if trusted_code is None:\\n        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=disabled_detail)\\n    return trusted_code\\n\\n\\ndef enforce_catalog_policy_for_component_type(\\n    component_type: str,\\n    *,\\n    snapshot: CatalogPolicySnapshot,\\n) -> None:\\n    \\\"\\\"\\\"Deny a materialized custom component whose canonical identity is blocked.\\\"\\\"\\\"\\n    try:\\n        validate_catalog_policy_for_component_type(component_type, snapshot=snapshot)\\n    except CatalogPolicyValidationError as exc:\\n        raise CatalogPolicyHTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=str(exc)) from exc\\n    except CatalogPolicyIdentityUnavailableError as exc:\\n        raise HTTPException(status_code=status.HTTP_503_SERVICE_UNAVAILABLE, detail=str(exc)) from exc\\n\"}]}";
